"""Hand-authored exercises; paired techniques, MySQL 8.0.28 syntax only."""


def S(number, question, sql, alt, explanation, pattern, tags, techniques):
    return dict(id='SQL3-%03d' % number, question=question, sql=sql, alt=alt,
                explanation=explanation, pattern=pattern, tags=tags.split('|'),
                techniques=techniques.split('|'), difficulty=4, cmp='set')


SQL3 = [
 S(1, 'For each customer, shipper and product category combination, return IDs, company names and discounted line revenue rounded to cents.',
   "SELECT customer.ID, customer.Company, shipper.ID, shipper.Company, product.Category, ROUND(SUM(line.Quantity*line.`Unit Price`*(1-line.Discount)),2) FROM customers customer JOIN orders ord ON ord.`Customer ID`=customer.ID JOIN shippers shipper ON shipper.ID=ord.`Shipper ID` JOIN `order details` line ON line.`Order ID`=ord.`Order ID` JOIN products product ON product.ID=line.`Product ID` GROUP BY customer.ID, customer.Company, shipper.ID, shipper.Company, product.Category;",
   "WITH category_sales AS (SELECT ord.`Customer ID` customer_id, ord.`Shipper ID` shipper_id, product.Category, SUM(line.Quantity*line.`Unit Price`*(1-line.Discount)) revenue FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` JOIN products product ON product.ID=line.`Product ID` GROUP BY ord.`Customer ID`, ord.`Shipper ID`, product.Category) SELECT customer.ID, customer.Company, shipper.ID, shipper.Company, category_sales.Category, ROUND(category_sales.revenue,2) FROM category_sales JOIN customers customer ON customer.ID=category_sales.customer_id JOIN shippers shipper ON shipper.ID=category_sales.shipper_id;",
   'Revenue uses actual line prices after Discount; shipping and taxes are excluded. Only existing customer/assigned-shipper/category combinations appear; aggregate before joining descriptive entities in the alternative.', 'inner_join', 'revenue|customer|shipper|category', 'five-table grouped join|preaggregated CTE'),
 S(2, 'Show employee ID, customer company and category with the discounted revenue that employee handled for that customer in that category.',
   "SELECT employee.ID, customer.ID, customer.Company, product.Category, ROUND(SUM(line.Quantity*line.`Unit Price`*(1-line.Discount)),2) FROM employees employee JOIN orders ord ON ord.`Employee ID`=employee.ID JOIN customers customer ON customer.ID=ord.`Customer ID` JOIN `order details` line ON line.`Order ID`=ord.`Order ID` JOIN products product ON product.ID=line.`Product ID` GROUP BY employee.ID, customer.ID, customer.Company, product.Category;",
   "SELECT DISTINCT employee.ID, customer.ID, customer.Company, product.Category, ROUND(SUM(line.Quantity*line.`Unit Price`*(1-line.Discount)) OVER (PARTITION BY employee.ID, customer.ID, product.Category),2) FROM employees employee JOIN orders ord ON ord.`Employee ID`=employee.ID JOIN customers customer ON customer.ID=ord.`Customer ID` JOIN `order details` line ON line.`Order ID`=ord.`Order ID` JOIN products product ON product.ID=line.`Product ID`;",
   'One row per employee/customer/category, not per order; customer ID prevents equal company names collapsing. The window alternative retains lines until DISTINCT collapses identical partition results.', 'inner_join', 'employee|customer|category|discounted revenue', 'grouped join|partitioned window'),
 S(3, 'List invoice ID and invoice date with order ID, customer company and responsible employee first and last names.',
   "SELECT invoice.`Invoice ID`, invoice.`Invoice Date`, ord.`Order ID`, customer.Company, employee.`First Name`, employee.`Last Name` FROM invoices invoice JOIN orders ord ON ord.`Order ID`=invoice.`Order ID` JOIN customers customer ON customer.ID=ord.`Customer ID` JOIN employees employee ON employee.ID=ord.`Employee ID`;",
   "SELECT invoice.`Invoice ID`, invoice.`Invoice Date`, ord.`Order ID`, (SELECT customer.Company FROM customers customer WHERE customer.ID=ord.`Customer ID`), (SELECT employee.`First Name` FROM employees employee WHERE employee.ID=ord.`Employee ID`), (SELECT employee.`Last Name` FROM employees employee WHERE employee.ID=ord.`Employee ID`) FROM invoices invoice JOIN orders ord ON ord.`Order ID`=invoice.`Order ID` WHERE EXISTS (SELECT 1 FROM customers customer WHERE customer.ID=ord.`Customer ID`) AND EXISTS (SELECT 1 FROM employees employee WHERE employee.ID=ord.`Employee ID`);",
   'Invoice date, not order date, is returned. Inner-join semantics omit orphaned invoices or unresolved customers/employees; EXISTS preserves that interpretation in the scalar-subquery alternative.', 'inner_join', 'invoice|employee|customer|invoice date', 'four-table join|correlated scalar lookups'),
 S(4, 'For each supplier and product actually procured, show supplier ID/company, product ID/name and total purchase quantity times unit cost.',
   "SELECT supplier.ID, supplier.Company, product.ID, product.`Product Name`, ROUND(SUM(detail.Quantity*detail.`Unit Cost`),2) FROM suppliers supplier JOIN `purchase orders` purchase ON purchase.`Supplier ID`=supplier.ID JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` JOIN products product ON product.ID=detail.`Product ID` GROUP BY supplier.ID, supplier.Company, product.ID, product.`Product Name`;",
   "SELECT DISTINCT supplier.ID, supplier.Company, product.ID, product.`Product Name`, ROUND(SUM(detail.Quantity*detail.`Unit Cost`) OVER (PARTITION BY supplier.ID, product.ID),2) FROM suppliers supplier JOIN `purchase orders` purchase ON purchase.`Supplier ID`=supplier.ID JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` JOIN products product ON product.ID=detail.`Product ID`;",
   'Procurement means purchase-order detail value, regardless of receipt or payment. Supplier identity comes from purchase orders, never by equating the textual Supplier IDs list to an integer.', 'inner_join', 'supplier|purchase orders|product|cost', 'group aggregate|window aggregate'),
 S(5, 'List inventory transaction ID, type name, product name and linked sales-order customer company; retain movements with no customer order.',
   "SELECT movement.`Transaction ID`, kind.`Type Name`, product.`Product Name`, customer.Company FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` JOIN products product ON product.ID=movement.`Product ID` LEFT JOIN orders ord ON ord.`Order ID`=movement.`Customer Order ID` LEFT JOIN customers customer ON customer.ID=ord.`Customer ID`;",
   "SELECT movement.`Transaction ID`, (SELECT kind.`Type Name` FROM `inventory transaction types` kind WHERE kind.ID=movement.`Transaction Type`), (SELECT product.`Product Name` FROM products product WHERE product.ID=movement.`Product ID`), (SELECT customer.Company FROM orders ord JOIN customers customer ON customer.ID=ord.`Customer ID` WHERE ord.`Order ID`=movement.`Customer Order ID`) FROM `inventory transactions` movement WHERE EXISTS (SELECT 1 FROM products product WHERE product.ID=movement.`Product ID`) AND EXISTS (SELECT 1 FROM `inventory transaction types` kind WHERE kind.ID=movement.`Transaction Type`);",
   'Transaction Type references inventory transaction types.ID; there is no inventory Status column. Missing sales links yield NULL company, not a lost ledger row.', 'left_join', 'inventory|transaction type|customer|product', 'five-table outer join|scalar correlations'),
 S(6, 'List received purchase lines with purchase order ID, supplier company, creator last name, product name, receipt date and quantity.',
   "SELECT purchase.`Purchase Order ID`, supplier.Company, employee.`Last Name`, product.`Product Name`, detail.`Date Received`, detail.Quantity FROM `purchase orders` purchase JOIN suppliers supplier ON supplier.ID=purchase.`Supplier ID` JOIN employees employee ON employee.ID=purchase.`Created By` JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` JOIN products product ON product.ID=detail.`Product ID` WHERE detail.`Date Received` IS NOT NULL;",
   "SELECT purchase.`Purchase Order ID`, (SELECT supplier.Company FROM suppliers supplier WHERE supplier.ID=purchase.`Supplier ID`), (SELECT employee.`Last Name` FROM employees employee WHERE employee.ID=purchase.`Created By`), (SELECT product.`Product Name` FROM products product WHERE product.ID=detail.`Product ID`), detail.`Date Received`, detail.Quantity FROM `purchase order details` detail JOIN `purchase orders` purchase ON purchase.`Purchase Order ID`=detail.`Purchase Order ID` WHERE detail.`Date Received` IS NOT NULL AND purchase.`Supplier ID` IN (SELECT ID FROM suppliers) AND purchase.`Created By` IN (SELECT ID FROM employees) AND detail.`Product ID` IN (SELECT ID FROM products);",
   'Received means a non-NULL detail Date Received, not header status. Each detail is retained separately, even when several lines refer to the same product.', 'inner_join', 'purchase receipt|supplier|creator|product', 'five-table join|membership and scalar lookups'),
 S(7, 'For each customer and product category, sum quantities from shipped orders only, returning customer ID/company and category.',
   "SELECT customer.ID, customer.Company, product.Category, SUM(line.Quantity) FROM customers customer JOIN orders ord ON ord.`Customer ID`=customer.ID JOIN `order details` line ON line.`Order ID`=ord.`Order ID` JOIN products product ON product.ID=line.`Product ID` WHERE ord.`Shipped Date` IS NOT NULL GROUP BY customer.ID, customer.Company, product.Category;",
   "SELECT customer.ID, customer.Company, summary.Category, summary.quantity FROM customers customer JOIN (SELECT ord.`Customer ID` customer_id, product.Category, SUM(line.Quantity) quantity FROM `order details` line JOIN products product ON product.ID=line.`Product ID` JOIN orders ord ON ord.`Order ID`=line.`Order ID` WHERE ord.`Shipped Date` IS NOT NULL GROUP BY ord.`Customer ID`, product.Category) summary ON summary.customer_id=customer.ID;",
   'A shipped order has a non-NULL Shipped Date; order status is not substituted. Quantities are not multiplied by invoice counts.', 'group_having', 'shipped|customer|category|quantity', 'grouped four-table join|preaggregated derived table'),
 S(8, 'Find order lines with Unit Price below the current product List Price; show line ID, order date, customer company, product name and both prices.',
   "SELECT line.ID, ord.`Order Date`, customer.Company, product.`Product Name`, line.`Unit Price`, product.`List Price` FROM `order details` line JOIN orders ord ON ord.`Order ID`=line.`Order ID` JOIN customers customer ON customer.ID=ord.`Customer ID` JOIN products product ON product.ID=line.`Product ID` WHERE line.`Unit Price`<product.`List Price`;",
   "SELECT line.ID, ord.`Order Date`, (SELECT customer.Company FROM customers customer WHERE customer.ID=ord.`Customer ID`), (SELECT product.`Product Name` FROM products product WHERE product.ID=line.`Product ID`), line.`Unit Price`, (SELECT product.`List Price` FROM products product WHERE product.ID=line.`Product ID`) FROM `order details` line JOIN orders ord ON ord.`Order ID`=line.`Order ID` WHERE EXISTS (SELECT 1 FROM products product WHERE product.ID=line.`Product ID` AND line.`Unit Price`<product.`List Price`) AND EXISTS (SELECT 1 FROM customers customer WHERE customer.ID=ord.`Customer ID`);",
   'Compare the charged unit price before Discount with the current catalogue, not historical catalogue prices. NULL prices do not satisfy the strict comparison.', 'inner_join', 'unit price|list price|customer|order date', 'four-table join|correlated EXISTS'),
 S(9, 'List invoice ID, order ID, shipper company and invoice Shipping for invoices whose order has an assigned valid shipper.',
   "SELECT invoice.`Invoice ID`, ord.`Order ID`, shipper.Company, invoice.Shipping FROM invoices invoice JOIN orders ord ON ord.`Order ID`=invoice.`Order ID` JOIN shippers shipper ON shipper.ID=ord.`Shipper ID`;",
   "SELECT invoice.`Invoice ID`, invoice.`Order ID`, (SELECT shipper.Company FROM shippers shipper WHERE shipper.ID=ord.`Shipper ID`), invoice.Shipping FROM invoices invoice JOIN orders ord ON ord.`Order ID`=invoice.`Order ID` WHERE ord.`Shipper ID` IN (SELECT ID FROM shippers);",
   'An assigned shipper does not prove shipment occurred. Invoice Shipping is shown as stored; it is not replaced by the order header Shipping Fee.', 'inner_join', 'invoice|shipper|shipping charge', 'three-table join|scalar membership'),
 S(10, 'For sales lines linked to a purchase order, show line ID, customer company, product name, supplier company and that purchase order ID.',
   "SELECT line.ID, customer.Company, product.`Product Name`, supplier.Company, purchase.`Purchase Order ID` FROM `order details` line JOIN orders ord ON ord.`Order ID`=line.`Order ID` JOIN customers customer ON customer.ID=ord.`Customer ID` JOIN products product ON product.ID=line.`Product ID` JOIN `purchase orders` purchase ON purchase.`Purchase Order ID`=line.`Purchase Order ID` JOIN suppliers supplier ON supplier.ID=purchase.`Supplier ID`;",
   "SELECT line.ID, (SELECT customer.Company FROM orders ord JOIN customers customer ON customer.ID=ord.`Customer ID` WHERE ord.`Order ID`=line.`Order ID`), (SELECT product.`Product Name` FROM products product WHERE product.ID=line.`Product ID`), (SELECT supplier.Company FROM `purchase orders` purchase JOIN suppliers supplier ON supplier.ID=purchase.`Supplier ID` WHERE purchase.`Purchase Order ID`=line.`Purchase Order ID`), line.`Purchase Order ID` FROM `order details` line WHERE EXISTS (SELECT 1 FROM orders ord JOIN customers customer ON customer.ID=ord.`Customer ID` WHERE ord.`Order ID`=line.`Order ID`) AND EXISTS (SELECT 1 FROM products product WHERE product.ID=line.`Product ID`) AND EXISTS (SELECT 1 FROM `purchase orders` purchase JOIN suppliers supplier ON supplier.ID=purchase.`Supplier ID` WHERE purchase.`Purchase Order ID`=line.`Purchase Order ID`);",
   'This follows the explicit line Purchase Order ID, not a guessed supplier-list match. It reports linkage, not a guarantee that a matching purchase detail was received.', 'inner_join', 'purchase linkage|sales line|supplier', 'linked multi-table join|correlated lookups'),
 S(11, 'Which catalogue categories have the highest product count? Return each tied category and its count.',
   "SELECT Category, COUNT(*) FROM products GROUP BY Category HAVING COUNT(*) >= ALL (SELECT COUNT(*) FROM products GROUP BY Category);",
   "SELECT Category, quantity FROM (SELECT Category, COUNT(*) quantity, DENSE_RANK() OVER (ORDER BY COUNT(*) DESC) position FROM products GROUP BY Category) ranked WHERE position=1;",
   'All ties at the maximum count are retained. A NULL category, if present, is one group; COUNT(*) counts its products as well.', 'group_having', 'category|highest count|include ties', 'HAVING ALL|window dense rank'),
 S(12, 'Find customers handled by the highest number of different employees; show customer ID, company and distinct employee count, including ties.',
   "SELECT customer.ID, customer.Company, COUNT(DISTINCT ord.`Employee ID`) FROM customers customer JOIN orders ord ON ord.`Customer ID`=customer.ID GROUP BY customer.ID, customer.Company HAVING COUNT(DISTINCT ord.`Employee ID`)=(SELECT MAX(quantity) FROM (SELECT COUNT(DISTINCT `Employee ID`) quantity FROM orders GROUP BY `Customer ID`) counts);",
   "WITH counts AS (SELECT customer.ID, customer.Company, COUNT(DISTINCT ord.`Employee ID`) quantity, RANK() OVER (ORDER BY COUNT(DISTINCT ord.`Employee ID`) DESC) position FROM customers customer JOIN orders ord ON ord.`Customer ID`=customer.ID GROUP BY customer.ID, customer.Company) SELECT ID, Company, quantity FROM counts WHERE position=1;",
   'Only customers with orders compete; NULL employee IDs are not distinct employees. Keep every customer tied at the maximum.', 'group_having', 'customer|different employees|highest|include ties', 'HAVING scalar maximum|window rank'),
 S(13, 'Among suppliers with purchase orders, return every supplier tied for the fewest purchase orders, with ID, company and order count.',
   "SELECT supplier.ID, supplier.Company, COUNT(*) FROM suppliers supplier JOIN `purchase orders` purchase ON purchase.`Supplier ID`=supplier.ID GROUP BY supplier.ID, supplier.Company HAVING COUNT(*)<=ALL (SELECT COUNT(*) FROM `purchase orders` GROUP BY `Supplier ID`);",
   "SELECT ID, Company, quantity FROM (SELECT supplier.ID, supplier.Company, COUNT(*) quantity, DENSE_RANK() OVER (ORDER BY COUNT(*)) position FROM suppliers supplier JOIN `purchase orders` purchase ON purchase.`Supplier ID`=supplier.ID GROUP BY supplier.ID, supplier.Company) ranked WHERE position=1;",
   'The competition excludes suppliers with zero purchase orders. Fewest includes ties; it does not mean LIMIT 1.', 'group_having', 'supplier|fewest|purchase orders|include ties', 'HAVING quantified comparison|window rank'),
 S(14, 'For every employee count shipped and unshipped orders placed in the first quarter of 2006 in separate columns, including zero counts.',
   "SELECT employee.ID, SUM(CASE WHEN ord.`Order ID` IS NOT NULL AND ord.`Shipped Date` IS NOT NULL THEN 1 ELSE 0 END), SUM(CASE WHEN ord.`Order ID` IS NOT NULL AND ord.`Shipped Date` IS NULL THEN 1 ELSE 0 END) FROM employees employee LEFT JOIN orders ord ON ord.`Employee ID`=employee.ID AND ord.`Order Date`>='2006-01-01' AND ord.`Order Date`<'2006-04-01' GROUP BY employee.ID;",
   "SELECT employee.ID, (SELECT COUNT(*) FROM orders ord WHERE ord.`Employee ID`=employee.ID AND ord.`Order Date`>='2006-01-01' AND ord.`Order Date`<'2006-04-01' AND ord.`Shipped Date` IS NOT NULL), (SELECT COUNT(*) FROM orders ord WHERE ord.`Employee ID`=employee.ID AND ord.`Order Date`>='2006-01-01' AND ord.`Order Date`<'2006-04-01' AND ord.`Shipped Date` IS NULL) FROM employees employee;",
   'Quarter membership uses Order Date; shipment uses Shipped Date. Checking the joined order key prevents the outer-join placeholder from being counted as an unshipped order.', 'cond_agg', 'employee|shipped|unshipped|first quarter', 'conditional outer aggregation|correlated counts'),
 S(15, 'For every customer count invoices with and without a Due Date, returning zeros for customers without invoices.',
   "SELECT customer.ID, COUNT(invoice.`Due Date`), COUNT(invoice.`Invoice ID`)-COUNT(invoice.`Due Date`) FROM customers customer LEFT JOIN orders ord ON ord.`Customer ID`=customer.ID LEFT JOIN invoices invoice ON invoice.`Order ID`=ord.`Order ID` GROUP BY customer.ID;",
   "SELECT customer.ID, (SELECT COUNT(*) FROM invoices invoice JOIN orders ord ON ord.`Order ID`=invoice.`Order ID` WHERE ord.`Customer ID`=customer.ID AND invoice.`Due Date` IS NOT NULL), (SELECT COUNT(*) FROM invoices invoice JOIN orders ord ON ord.`Order ID`=invoice.`Order ID` WHERE ord.`Customer ID`=customer.ID AND invoice.`Due Date` IS NULL) FROM customers customer;",
   'Missing Due Date is not interpreted as overdue. All Due Dates in this dump are NULL; the counts still distinguish customers with invoices from those without.', 'cond_agg', 'customer|invoice|due date|null', 'outer-join counts|scalar conditional counts'),
 S(16, 'For every product return Purchased, Sold and Waste inventory quantities in three columns, using zero for missing movement types.',
   "SELECT product.ID, SUM(CASE WHEN kind.`Type Name`='Purchased' THEN COALESCE(movement.Quantity,0) ELSE 0 END), SUM(CASE WHEN kind.`Type Name`='Sold' THEN COALESCE(movement.Quantity,0) ELSE 0 END), SUM(CASE WHEN kind.`Type Name`='Waste' THEN COALESCE(movement.Quantity,0) ELSE 0 END) FROM products product LEFT JOIN `inventory transactions` movement ON movement.`Product ID`=product.ID LEFT JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` GROUP BY product.ID;",
   "SELECT product.ID, COALESCE((SELECT SUM(movement.Quantity) FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE movement.`Product ID`=product.ID AND kind.`Type Name`='Purchased'),0), COALESCE((SELECT SUM(movement.Quantity) FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE movement.`Product ID`=product.ID AND kind.`Type Name`='Sold'),0), COALESCE((SELECT SUM(movement.Quantity) FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE movement.`Product ID`=product.ID AND kind.`Type Name`='Waste'),0) FROM products product;",
   'Quantities are unsigned type-specific totals, not stock on hand; NULL quantities are displayed as zero for this diagnostic; On Hold is excluded. The numeric Transaction Type is resolved through inventory transaction types.', 'cond_agg', 'inventory|Purchased|Sold|Waste|pivot', 'conditional aggregation|independent correlated sums'),
 S(17, 'Return orders containing Beverages and at least two distinct non-NULL product categories, with the category count.',
   "SELECT line.`Order ID`, COUNT(DISTINCT product.Category) FROM `order details` line JOIN products product ON product.ID=line.`Product ID` GROUP BY line.`Order ID` HAVING COUNT(DISTINCT product.Category)>=2 AND SUM(product.Category='Beverages')>0;",
   "SELECT ord.`Order ID`, (SELECT COUNT(DISTINCT product.Category) FROM `order details` line JOIN products product ON product.ID=line.`Product ID` WHERE line.`Order ID`=ord.`Order ID`) FROM orders ord WHERE EXISTS (SELECT 1 FROM `order details` line JOIN products product ON product.ID=line.`Product ID` WHERE line.`Order ID`=ord.`Order ID` AND product.Category='Beverages') AND (SELECT COUNT(DISTINCT product.Category) FROM `order details` line JOIN products product ON product.ID=line.`Product ID` WHERE line.`Order ID`=ord.`Order ID`)>=2;",
   'Count categories, not lines or products. Beverages is required in addition to the two-category threshold; NULL categories do not contribute to COUNT DISTINCT.', 'group_having', 'orders|Beverages|at least|categories', 'HAVING conditional sum|EXISTS and scalar cardinality'),
 S(18, 'For each purchase order show counts of received and not-yet-received detail lines, including purchase orders with no details.',
   "SELECT purchase.`Purchase Order ID`, COUNT(detail.`Date Received`), COUNT(detail.ID)-COUNT(detail.`Date Received`) FROM `purchase orders` purchase LEFT JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` GROUP BY purchase.`Purchase Order ID`;",
   "SELECT purchase.`Purchase Order ID`, (SELECT COUNT(*) FROM `purchase order details` detail WHERE detail.`Purchase Order ID`=purchase.`Purchase Order ID` AND detail.`Date Received` IS NOT NULL), (SELECT COUNT(*) FROM `purchase order details` detail WHERE detail.`Purchase Order ID`=purchase.`Purchase Order ID` AND detail.`Date Received` IS NULL) FROM `purchase orders` purchase;",
   'A detail is received iff Date Received is non-NULL. COUNT(detail.ID), rather than COUNT(*), excludes the synthetic outer-join row.', 'cond_agg', 'purchase order|received|unreceived|line count', 'outer aggregate|correlated counts'),
 S(19, 'Find customer/product combinations purchased on at least two different orders, returning customer ID, product ID and distinct order count.',
   "SELECT ord.`Customer ID`, line.`Product ID`, COUNT(DISTINCT ord.`Order ID`) FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` GROUP BY ord.`Customer ID`, line.`Product ID` HAVING COUNT(DISTINCT ord.`Order ID`)>=2;",
   "WITH purchases AS (SELECT DISTINCT ord.`Customer ID` customer_id, line.`Product ID` product_id, ord.`Order ID` order_id FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID`) SELECT DISTINCT customer_id, product_id, COUNT(*) OVER (PARTITION BY customer_id, product_id) FROM purchases current_purchase WHERE EXISTS (SELECT 1 FROM purchases other_purchase WHERE other_purchase.customer_id=current_purchase.customer_id AND other_purchase.product_id=current_purchase.product_id AND other_purchase.order_id<>current_purchase.order_id);",
   'Repeated detail lines on one order are not repeat purchases. The alternative deduplicates the order/customer/product relation before counting via a window.', 'group_having', 'customer|reordered|product|different orders', 'HAVING distinct count|deduplicated window and EXISTS'),
 S(20, 'Using only lines with known quantity, unit price and discount, calculate the gross-value-weighted discount rate per represented category, rounded to six decimals.',
   "SELECT product.Category, ROUND(SUM(line.Quantity*line.`Unit Price`*line.Discount)/NULLIF(SUM(line.Quantity*line.`Unit Price`),0),6) FROM products product JOIN `order details` line ON line.`Product ID`=product.ID WHERE line.Quantity IS NOT NULL AND line.`Unit Price` IS NOT NULL AND line.Discount IS NOT NULL GROUP BY product.Category;",
   "WITH weighted AS (SELECT product.Category,SUM(line.Quantity*line.`Unit Price`*line.Discount) OVER (PARTITION BY product.Category) discount_value,SUM(line.Quantity*line.`Unit Price`) OVER (PARTITION BY product.Category) gross_value FROM products product JOIN `order details` line ON line.`Product ID`=product.ID WHERE line.Quantity IS NOT NULL AND line.`Unit Price` IS NOT NULL AND line.Discount IS NOT NULL) SELECT DISTINCT Category,ROUND(discount_value/NULLIF(gross_value,0),6) FROM weighted;",
   'Incomplete lines are excluded from both numerator and denominator; categories without complete lines are omitted. Weight each discount fraction by Quantity times Unit Price; do not use an unweighted AVG(Discount). A zero denominator gives NULL; only categories with detail lines appear.', 'computed', 'category|weighted discount|ratio', 'grouped weighted ratio|window weighted ratio'),
 S(21, 'List customer ID/company for customers with orders but no invoice on any of their orders.',
   "SELECT customer.ID, customer.Company FROM customers customer WHERE EXISTS (SELECT 1 FROM orders ord WHERE ord.`Customer ID`=customer.ID) AND NOT EXISTS (SELECT 1 FROM orders ord JOIN invoices invoice ON invoice.`Order ID`=ord.`Order ID` WHERE ord.`Customer ID`=customer.ID);",
   "SELECT customer.ID, customer.Company FROM customers customer JOIN orders ord ON ord.`Customer ID`=customer.ID LEFT JOIN invoices invoice ON invoice.`Order ID`=ord.`Order ID` GROUP BY customer.ID, customer.Company HAVING COUNT(invoice.`Invoice ID`)=0;",
   'The customer must have at least one order, and none may be invoiced. This is stronger than having one uninvoiced order.', 'not_exists', 'customer|orders|no invoices', 'EXISTS and NOT EXISTS|outer join HAVING zero'),
 S(22, 'Find ordered products that have no Waste inventory transaction; return product ID and name.',
   "SELECT product.ID, product.`Product Name` FROM products product WHERE EXISTS (SELECT 1 FROM `order details` line WHERE line.`Product ID`=product.ID) AND NOT EXISTS (SELECT 1 FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE movement.`Product ID`=product.ID AND kind.`Type Name`='Waste');",
   "SELECT DISTINCT product.ID, product.`Product Name` FROM products product JOIN `order details` line ON line.`Product ID`=product.ID LEFT JOIN (SELECT movement.`Product ID` product_id FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE kind.`Type Name`='Waste') waste ON waste.product_id=product.ID WHERE waste.product_id IS NULL;",
   'At least one sales detail is required; no Waste movement is allowed at any time. Sold movements are not a substitute for order details in the positive condition.', 'not_exists', 'ordered products|never Waste|inventory', 'semi and anti EXISTS|left anti join'),
 S(23, 'List unreceived purchase detail ID, purchase order ID, supplier company and product name.',
   "SELECT detail.ID, purchase.`Purchase Order ID`, supplier.Company, product.`Product Name` FROM `purchase order details` detail JOIN `purchase orders` purchase ON purchase.`Purchase Order ID`=detail.`Purchase Order ID` JOIN suppliers supplier ON supplier.ID=purchase.`Supplier ID` JOIN products product ON product.ID=detail.`Product ID` WHERE detail.`Date Received` IS NULL;",
   "SELECT detail.ID, detail.`Purchase Order ID`, (SELECT supplier.Company FROM `purchase orders` purchase JOIN suppliers supplier ON supplier.ID=purchase.`Supplier ID` WHERE purchase.`Purchase Order ID`=detail.`Purchase Order ID`), (SELECT product.`Product Name` FROM products product WHERE product.ID=detail.`Product ID`) FROM `purchase order details` detail WHERE detail.`Date Received` IS NULL AND EXISTS (SELECT 1 FROM `purchase orders` purchase JOIN suppliers supplier ON supplier.ID=purchase.`Supplier ID` WHERE purchase.`Purchase Order ID`=detail.`Purchase Order ID`) AND detail.`Product ID` IN (SELECT ID FROM products);",
   'Unreceived is defined only by NULL Date Received. Header status and Posted To Inventory measure different facts.', 'null_handling', 'purchase detail|unreceived|supplier|product', 'four-table join|correlated scalar lookups'),
 S(24, 'Return uninvoiced order IDs with their customer company, regardless of shipment or payment state.',
   "SELECT ord.`Order ID`, customer.Company FROM orders ord JOIN customers customer ON customer.ID=ord.`Customer ID` WHERE NOT EXISTS (SELECT 1 FROM invoices invoice WHERE invoice.`Order ID`=ord.`Order ID`);",
   "SELECT ord.`Order ID`, customer.Company FROM orders ord JOIN customers customer ON customer.ID=ord.`Customer ID` LEFT JOIN invoices invoice ON invoice.`Order ID`=ord.`Order ID` WHERE invoice.`Invoice ID` IS NULL;",
   'No matching invoice is the only negative condition. Use the nonnullable invoice primary key as the anti-join NULL test.', 'not_exists', 'order|customer|no invoice', 'NOT EXISTS|left anti join'),
 S(25, 'Which shippers have no orders shipped during May 2006? Return shipper ID and company, including unused shippers.',
   "SELECT shipper.ID, shipper.Company FROM shippers shipper WHERE NOT EXISTS (SELECT 1 FROM orders ord WHERE ord.`Shipper ID`=shipper.ID AND ord.`Shipped Date`>='2006-05-01' AND ord.`Shipped Date`<'2006-06-01');",
   "SELECT shipper.ID, shipper.Company FROM shippers shipper LEFT JOIN orders ord ON ord.`Shipper ID`=shipper.ID AND ord.`Shipped Date`>='2006-05-01' AND ord.`Shipped Date`<'2006-06-01' WHERE ord.`Order ID` IS NULL;",
   'The time filter uses Shipped Date, not Order Date. A carrier with orders outside May still qualifies; NULL shipment dates are not May shipments. May gives a nonempty anti-join on this dump.', 'not_exists', 'shipper|no shipped orders|May', 'correlated anti-subquery|range-qualified outer anti join'),
 S(26, 'List employee pairs in the same non-NULL city with different non-NULL job titles; each pair once, returning IDs and city.',
   "SELECT first_employee.ID, second_employee.ID, first_employee.City FROM employees first_employee JOIN employees second_employee ON first_employee.City=second_employee.City AND first_employee.ID<second_employee.ID WHERE first_employee.`Job Title`<>second_employee.`Job Title`;",
   "SELECT first_employee.ID, second_employee.ID, first_employee.City FROM employees first_employee CROSS JOIN employees second_employee WHERE first_employee.ID<second_employee.ID AND EXISTS (SELECT 1 FROM employees match_employee WHERE match_employee.ID=second_employee.ID AND match_employee.City=first_employee.City AND match_employee.`Job Title`<>first_employee.`Job Title`);",
   'IDs impose one orientation per pair. Ordinary equality/inequality deliberately exclude unknown cities or titles; a self match cannot pass ID ordering.', 'self_join', 'employee pairs|city|different job title', 'self join|cross join with correlated EXISTS'),
 S(27, 'Find unordered pairs of products in the same category whose positive list prices differ by at most 10% of the cheaper price; show both IDs and prices.',
   "SELECT cheaper.ID, dearer.ID, cheaper.`List Price`, dearer.`List Price` FROM products cheaper JOIN products dearer ON cheaper.Category=dearer.Category AND (cheaper.`List Price`<dearer.`List Price` OR (cheaper.`List Price`=dearer.`List Price` AND cheaper.ID<dearer.ID)) WHERE cheaper.`List Price`>0 AND dearer.`List Price`<=cheaper.`List Price`*1.10;",
   "WITH catalogues AS (SELECT Category,JSON_ARRAYAGG(JSON_OBJECT('id',ID,'price',`List Price`)) items FROM products WHERE Category IS NOT NULL GROUP BY Category) SELECT cheaper.product_id,dearer.product_id,cheaper.price,dearer.price FROM catalogues JOIN JSON_TABLE(catalogues.items,'$[*]' COLUMNS(product_id INT PATH '$.id',price DECIMAL(30,11) PATH '$.price')) cheaper ON TRUE JOIN JSON_TABLE(catalogues.items,'$[*]' COLUMNS(product_id INT PATH '$.id',price DECIMAL(30,11) PATH '$.price')) dearer ON TRUE WHERE cheaper.price>0 AND (cheaper.price,cheaper.product_id)<(dearer.price,dearer.product_id) AND dearer.price<=1.10*cheaper.price;",
   'Output is oriented by (price, ID), not necessarily ID alone. Equal positive prices qualify; the denominator is the cheaper price. The alternative independently groups categories into JSON arrays and expands candidate pairs with JSON_TABLE, available on 8.0.28.', 'self_join', 'product pairs|category|price difference|percent', 'self join interval|grouped JSON_TABLE expansion'),
 S(28, 'Return each customer order with its immediate next order ID for that customer, ordered logically by Order Date then Order ID; keep final orders with NULL successor.',
   "SELECT `Customer ID`, `Order ID`, LEAD(`Order ID`) OVER (PARTITION BY `Customer ID` ORDER BY `Order Date`, `Order ID`) FROM orders;",
   "SELECT current_order.`Customer ID`, current_order.`Order ID`, next_order.`Order ID` FROM orders current_order LEFT JOIN orders next_order ON next_order.`Customer ID`<=>current_order.`Customer ID` AND (COALESCE(next_order.`Order Date`,'1000-01-01'),next_order.`Order ID`)>(COALESCE(current_order.`Order Date`,'1000-01-01'),current_order.`Order ID`) AND NOT EXISTS (SELECT 1 FROM orders between_order WHERE between_order.`Customer ID`<=>current_order.`Customer ID` AND (COALESCE(between_order.`Order Date`,'1000-01-01'),between_order.`Order ID`)>(COALESCE(current_order.`Order Date`,'1000-01-01'),current_order.`Order ID`) AND (COALESCE(between_order.`Order Date`,'1000-01-01'),between_order.`Order ID`)<(COALESCE(next_order.`Order Date`,'1000-01-01'),next_order.`Order ID`));",
   'Successor uses timestamp then unique ID, so same-day orders are distinct. NULL dates sort first; the sentinel in the alternative precedes the dump dates. This is an adjacency result, not a promise of display sort order.', 'topn_rank', 'customer|next order|lead|date sequence', 'LEAD window|anti-intermediate self join'),
 S(29, 'Find pairs of customers in different known cities who ordered a common product; show customer IDs and product ID once per combination.',
   "SELECT DISTINCT first_customer.ID, second_customer.ID, first_line.`Product ID` FROM customers first_customer JOIN orders first_order ON first_order.`Customer ID`=first_customer.ID JOIN `order details` first_line ON first_line.`Order ID`=first_order.`Order ID` JOIN `order details` second_line ON second_line.`Product ID`=first_line.`Product ID` JOIN orders second_order ON second_order.`Order ID`=second_line.`Order ID` JOIN customers second_customer ON second_customer.ID=second_order.`Customer ID` WHERE first_customer.ID<second_customer.ID AND first_customer.City<>second_customer.City;",
   "SELECT first_customer.ID, second_customer.ID, product.ID FROM customers first_customer CROSS JOIN customers second_customer CROSS JOIN products product WHERE first_customer.ID<second_customer.ID AND first_customer.City<>second_customer.City AND EXISTS (SELECT 1 FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` WHERE ord.`Customer ID`=first_customer.ID AND line.`Product ID`=product.ID) AND EXISTS (SELECT 1 FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` WHERE ord.`Customer ID`=second_customer.ID AND line.`Product ID`=product.ID);",
   'Customer ID ordering removes reversed pairs. Repeated purchases must not duplicate the customer/customer/product tuple; unknown cities do not count as different.', 'self_join', 'customer pairs|common product|different city', 'shared-product multi-join|double correlated EXISTS'),
 S(30, 'Return products whose standard cost exceeds the costs of at least two other products in their category, with product ID and cost.',
   "SELECT product.ID, product.`Standard Cost` FROM products product WHERE (SELECT COUNT(*) FROM products cheaper WHERE cheaper.Category<=>product.Category AND cheaper.`Standard Cost`<product.`Standard Cost`)>=2;",
   "SELECT ID, `Standard Cost` FROM (SELECT ID, `Standard Cost`, RANK() OVER (PARTITION BY Category ORDER BY `Standard Cost`) position, COUNT(*) OVER (PARTITION BY Category)-COUNT(`Standard Cost`) OVER (PARTITION BY Category) null_count FROM products) ranked WHERE `Standard Cost` IS NOT NULL AND position-null_count>=3;",
   'Count cheaper products, not distinct cost levels: ties below still count as separate products. The window alternative subtracts NULL peers so NULL costs never count as cheaper.', 'correlated', 'product|standard cost|category|at least two', 'correlated cheaper count|RANK with NULL correction'),
 S(31, 'Return every product at the second highest distinct non-NULL standard cost within its category, retaining ties; show ID, category and cost.',
   "SELECT ID, Category, `Standard Cost` FROM (SELECT ID, Category, `Standard Cost`, DENSE_RANK() OVER (PARTITION BY Category ORDER BY `Standard Cost` DESC) position FROM products WHERE `Standard Cost` IS NOT NULL) ranked WHERE position=2;",
   "SELECT product.ID, product.Category, product.`Standard Cost` FROM products product WHERE product.`Standard Cost` IS NOT NULL AND (SELECT COUNT(DISTINCT dearer.`Standard Cost`) FROM products dearer WHERE dearer.Category<=>product.Category AND dearer.`Standard Cost`>product.`Standard Cost`)=1;",
   'Second highest means one distinct higher cost, not the second row. Categories with fewer than two distinct non-NULL costs contribute no rows.', 'topn_rank', 'second highest|standard cost|category|include ties', 'DENSE_RANK|correlated distinct count'),
 S(32, 'Choose at most two cheapest products per category by List Price ascending then ID ascending; exclude NULL prices and return ID, category and price.',
   "SELECT ID, Category, `List Price` FROM (SELECT ID, Category, `List Price`, ROW_NUMBER() OVER (PARTITION BY Category ORDER BY `List Price`, ID) position FROM products WHERE `List Price` IS NOT NULL) ranked WHERE position<=2;",
   "SELECT product.ID, product.Category, product.`List Price` FROM products product WHERE product.`List Price` IS NOT NULL AND (SELECT COUNT(*) FROM products cheaper WHERE cheaper.Category<=>product.Category AND (cheaper.`List Price`<product.`List Price` OR (cheaper.`List Price`=product.`List Price` AND cheaper.ID<product.ID)))<2;",
   'Exactly two rows where a category has enough products; no additional tied prices. ID breaks price ties deterministically.', 'topn_rank', 'two cheapest|category|row number|drop ties', 'ROW_NUMBER|correlated predecessor count'),
 S(33, 'Return the two latest purchase orders per supplier by Creation Date descending then Purchase Order ID descending; show supplier ID, purchase order ID and date.',
   "SELECT `Supplier ID`, `Purchase Order ID`, `Creation Date` FROM (SELECT `Supplier ID`, `Purchase Order ID`, `Creation Date`, ROW_NUMBER() OVER (PARTITION BY `Supplier ID` ORDER BY `Creation Date` DESC, `Purchase Order ID` DESC) position FROM `purchase orders`) ranked WHERE position<=2;",
   "SELECT purchase.`Supplier ID`, purchase.`Purchase Order ID`, purchase.`Creation Date` FROM `purchase orders` purchase WHERE (SELECT COUNT(*) FROM `purchase orders` newer WHERE newer.`Supplier ID`<=>purchase.`Supplier ID` AND (COALESCE(newer.`Creation Date`,'1000-01-01'),newer.`Purchase Order ID`)>(COALESCE(purchase.`Creation Date`,'1000-01-01'),purchase.`Purchase Order ID`))<2;",
   'Latest uses Creation Date, never Submitted Date or receipt date. NULL creation dates sort last; ID resolves timestamp ties, so at most two rows appear per supplier.', 'topn_rank', 'purchase orders|latest two|supplier|creation date', 'ROW_NUMBER|correlated newer count'),
 S(34, 'For each customer select their earliest dated invoice, breaking invoice-date ties by Invoice ID; return customer ID, invoice ID and order ID.',
   "SELECT customer_id, invoice_id, order_id FROM (SELECT ord.`Customer ID` customer_id, invoice.`Invoice ID` invoice_id, ord.`Order ID` order_id, ROW_NUMBER() OVER (PARTITION BY ord.`Customer ID` ORDER BY invoice.`Invoice Date`, invoice.`Invoice ID`) position FROM invoices invoice JOIN orders ord ON ord.`Order ID`=invoice.`Order ID` WHERE invoice.`Invoice Date` IS NOT NULL) ranked WHERE position=1;",
   "SELECT ord.`Customer ID`, invoice.`Invoice ID`, ord.`Order ID` FROM invoices invoice JOIN orders ord ON ord.`Order ID`=invoice.`Order ID` WHERE invoice.`Invoice Date` IS NOT NULL AND NOT EXISTS (SELECT 1 FROM invoices earlier JOIN orders other_order ON other_order.`Order ID`=earlier.`Order ID` WHERE other_order.`Customer ID`<=>ord.`Customer ID` AND (earlier.`Invoice Date`,earlier.`Invoice ID`)<(invoice.`Invoice Date`,invoice.`Invoice ID`));",
   'Earliest invoice is based on Invoice Date, not the customer first order. Undated invoices are excluded; only one dated invoice is returned for each represented customer.', 'topn_rank', 'customer|earliest invoice|date', 'ROW_NUMBER|NOT EXISTS earlier invoice'),
 S(35, 'Show customer ID, order ID and cumulative shipping fees in Order Date then Order ID sequence for each customer, treating NULL fees as zero.',
   "SELECT `Customer ID`, `Order ID`, SUM(COALESCE(`Shipping Fee`,0)) OVER (PARTITION BY `Customer ID` ORDER BY `Order Date`, `Order ID` ROWS UNBOUNDED PRECEDING) FROM orders;",
   "SELECT ord.`Customer ID`, ord.`Order ID`, (SELECT SUM(COALESCE(prior.`Shipping Fee`,0)) FROM orders prior WHERE prior.`Customer ID`<=>ord.`Customer ID` AND (COALESCE(prior.`Order Date`,'1000-01-01'),prior.`Order ID`)<=(COALESCE(ord.`Order Date`,'1000-01-01'),ord.`Order ID`)) FROM orders ord;",
   'A row-based running total includes the current order. ID resolves equal dates; NULL dates sort first. Shipping is summed once per order, never per detail line.', 'topn_rank', 'running total|customer|shipping fees', 'SUM ROWS window|correlated prefix sum'),
 S(36, 'Compute each observed order gross line total and its moving average over that order and the previous two observed orders by Order Date and Order ID, rounded to cents.',
   "WITH totals AS (SELECT ord.`Order ID` order_id, ord.`Order Date` order_date, SUM(line.Quantity*line.`Unit Price`) gross FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` GROUP BY ord.`Order ID`,ord.`Order Date`) SELECT order_id, ROUND(gross,2), ROUND(AVG(gross) OVER (ORDER BY order_date,order_id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW),2) FROM totals;",
   "WITH totals AS (SELECT ord.`Order ID` order_id, ord.`Order Date` order_date, SUM(line.Quantity*line.`Unit Price`) gross FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` GROUP BY ord.`Order ID`,ord.`Order Date`), numbered AS (SELECT current_total.*, (SELECT COUNT(*) FROM totals prior WHERE (COALESCE(prior.order_date,'1000-01-01'),prior.order_id)<=(COALESCE(current_total.order_date,'1000-01-01'),current_total.order_id)) sequence_no FROM totals current_total) SELECT current_total.order_id, ROUND(current_total.gross,2), ROUND(AVG(prior.gross),2) FROM numbered current_total JOIN numbered prior ON prior.sequence_no BETWEEN current_total.sequence_no-2 AND current_total.sequence_no GROUP BY current_total.order_id,current_total.gross;",
   'Observed means orders with detail lines. This averages three orders, not three days; the first two frames contain fewer observations. Gross excludes discount, shipping and tax.', 'topn_rank', 'moving average|three orders|gross', 'AVG sliding frame|ordinal correlated self join'),
 S(37, 'Show discounted sales per observed order month, previous observed month sales, and the difference, rounded to cents; first previous value is NULL.',
   "WITH monthly AS (SELECT DATE_FORMAT(ord.`Order Date`,'%Y-%m') month_key, SUM(line.Quantity*line.`Unit Price`*(1-line.Discount)) sales FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` WHERE ord.`Order Date` IS NOT NULL GROUP BY DATE_FORMAT(ord.`Order Date`,'%Y-%m')) SELECT month_key, ROUND(sales,2), ROUND(LAG(sales) OVER (ORDER BY month_key),2), ROUND(sales-LAG(sales) OVER (ORDER BY month_key),2) FROM monthly;",
   "WITH monthly AS (SELECT DATE_FORMAT(ord.`Order Date`,'%Y-%m') month_key, SUM(line.Quantity*line.`Unit Price`*(1-line.Discount)) sales FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` WHERE ord.`Order Date` IS NOT NULL GROUP BY DATE_FORMAT(ord.`Order Date`,'%Y-%m')) SELECT current_month.month_key, ROUND(current_month.sales,2), ROUND(prior.sales,2), ROUND(current_month.sales-prior.sales,2) FROM monthly current_month LEFT JOIN monthly prior ON prior.month_key=(SELECT MAX(earlier.month_key) FROM monthly earlier WHERE earlier.month_key<current_month.month_key);",
   'Previous means previous observed month, not necessarily previous calendar month. Subtract unrounded totals before final rounding; missing previous sales stay NULL.', 'topn_rank', 'monthly sales|lag|change|discount', 'LAG|correlated previous-month self join'),
 S(38, 'Show product ID, Sold transaction ID and running Sold quantity by Transaction Created Date then Transaction ID per product.',
   "SELECT movement.`Product ID`, movement.`Transaction ID`, SUM(movement.Quantity) OVER (PARTITION BY movement.`Product ID` ORDER BY movement.`Transaction Created Date`,movement.`Transaction ID` ROWS UNBOUNDED PRECEDING) FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE kind.`Type Name`='Sold';",
   "SELECT movement.`Product ID`, movement.`Transaction ID`, (SELECT SUM(prior.Quantity) FROM `inventory transactions` prior JOIN `inventory transaction types` kind ON kind.ID=prior.`Transaction Type` WHERE kind.`Type Name`='Sold' AND prior.`Product ID`<=>movement.`Product ID` AND (COALESCE(prior.`Transaction Created Date`,'1000-01-01'),prior.`Transaction ID`)<=(COALESCE(movement.`Transaction Created Date`,'1000-01-01'),movement.`Transaction ID`)) FROM `inventory transactions` movement WHERE movement.`Transaction Type` IN (SELECT ID FROM `inventory transaction types` WHERE `Type Name`='Sold');",
   'Only Sold rows enter the running frame; other transaction types must not affect it. Equal timestamps are resolved by transaction ID; NULL timestamps sort first.', 'topn_rank', 'inventory|Sold|running quantity', 'filtered SUM window|correlated ledger prefix'),
 S(39, 'For every product show its percentage share of the sum of catalogue List Prices in its category, rounded to four decimals.',
   "SELECT ID, Category, ROUND(100*`List Price`/NULLIF(SUM(`List Price`) OVER (PARTITION BY Category),0),4) FROM products;",
   "SELECT product.ID, product.Category, ROUND(100*product.`List Price`/NULLIF((SELECT SUM(peer.`List Price`) FROM products peer WHERE peer.Category<=>product.Category),0),4) FROM products product;",
   'This is share of catalogue prices, not revenue or stock valuation. NULL prices remain NULL; a category with a zero total has undefined shares, represented as NULL.', 'computed', 'category|catalogue price|percentage share', 'partition total window|correlated denominator'),
 S(40, 'For each dated customer order return the calendar-day gap from the preceding dated order by date and ID; first gap is NULL.',
   "SELECT `Customer ID`, `Order ID`, DATEDIFF(`Order Date`,LAG(`Order Date`) OVER (PARTITION BY `Customer ID` ORDER BY `Order Date`,`Order ID`)) FROM orders WHERE `Order Date` IS NOT NULL;",
   "SELECT ord.`Customer ID`, ord.`Order ID`, DATEDIFF(ord.`Order Date`,(SELECT MAX(prior.`Order Date`) FROM orders prior WHERE prior.`Customer ID`<=>ord.`Customer ID` AND (prior.`Order Date`,prior.`Order ID`)<(ord.`Order Date`,ord.`Order ID`))) FROM orders ord WHERE ord.`Order Date` IS NOT NULL;",
   'DATEDIFF compares calendar dates, not elapsed 24-hour intervals. Same-date consecutive orders have gap zero; undated orders are excluded before finding predecessors.', 'topn_rank', 'customer|previous order|day gap', 'LAG date difference|correlated preceding maximum'),
 S(41, 'As of 1 July 2006, show unshipped orders placed before that date with their calendar age in days; return order ID and age.',
   "SELECT `Order ID`, DATEDIFF('2006-07-01',`Order Date`) FROM orders WHERE `Shipped Date` IS NULL AND `Order Date`<'2006-07-01';",
   "SELECT ord.`Order ID`, TO_DAYS('2006-07-01')-TO_DAYS(ord.`Order Date`) FROM orders ord WHERE NOT EXISTS (SELECT 1 FROM orders shipped WHERE shipped.`Order ID`=ord.`Order ID` AND shipped.`Shipped Date` IS NOT NULL) AND ord.`Order Date`<'2006-07-01';",
   'The reference date is fixed for reproducibility; this is not age today. Age is calendar-day distance, and unshipped means the dump has no Shipped Date.', 'date', 'unshipped|age|fixed date', 'DATEDIFF and NULL filter|TO_DAYS and anti-subquery'),
 S(42, 'Return order IDs and full elapsed days for orders shipped at least seven full days after placement.',
   "SELECT `Order ID`, TIMESTAMPDIFF(DAY,`Order Date`,`Shipped Date`) FROM orders WHERE TIMESTAMPDIFF(DAY,`Order Date`,`Shipped Date`)>=7;",
   "SELECT `Order ID`, FLOOR(TIMESTAMPDIFF(SECOND,`Order Date`,`Shipped Date`)/86400) FROM orders WHERE `Shipped Date`>=DATE_ADD(`Order Date`,INTERVAL 7 DAY);",
   'Seven full days means at least 168 hours in the stored DATETIME values, not merely seven calendar-date boundaries. NULL dates fail the filter.', 'date', 'shipment delay|at least seven days', 'TIMESTAMPDIFF day|date interval and seconds'),
 S(43, 'Return all twelve months of 2006 as YYYY-MM with order counts, including months with zero orders.',
   "WITH RECURSIVE months AS (SELECT DATE('2006-01-01') month_start UNION ALL SELECT DATE_ADD(month_start,INTERVAL 1 MONTH) FROM months WHERE month_start<'2006-12-01') SELECT DATE_FORMAT(months.month_start,'%Y-%m'), COUNT(ord.`Order ID`) FROM months LEFT JOIN orders ord ON ord.`Order Date`>=months.month_start AND ord.`Order Date`<DATE_ADD(months.month_start,INTERVAL 1 MONTH) GROUP BY months.month_start;",
   "SELECT CONCAT('2006-',LPAD(months.month_no,2,'0')), (SELECT COUNT(*) FROM orders ord WHERE YEAR(ord.`Order Date`)=2006 AND MONTH(ord.`Order Date`)=months.month_no) FROM (SELECT 1 month_no UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12) months;",
   'Generate a calendar rather than grouping only existing dates. The recursive main uses half-open month ranges; the literal-calendar alternative uses correlated counts and returns the same twelve buckets.', 'date', 'calendar|monthly orders|zero months|2006', 'recursive calendar outer join|literal calendar correlated count'),
 S(44, 'For each customer with dated orders show the first and last order dates within each observed calendar month, as dates without time.',
   "SELECT `Customer ID`, DATE_FORMAT(`Order Date`,'%Y-%m'), DATE(MIN(`Order Date`)), DATE(MAX(`Order Date`)) FROM orders WHERE `Order Date` IS NOT NULL GROUP BY `Customer ID`,DATE_FORMAT(`Order Date`,'%Y-%m');",
   "SELECT DISTINCT `Customer ID`, DATE_FORMAT(`Order Date`,'%Y-%m'), DATE(MIN(`Order Date`) OVER (PARTITION BY `Customer ID`,YEAR(`Order Date`),MONTH(`Order Date`))), DATE(MAX(`Order Date`) OVER (PARTITION BY `Customer ID`,YEAR(`Order Date`),MONTH(`Order Date`))) FROM orders WHERE `Order Date` IS NOT NULL;",
   'First/last refers to orders actually present, not the calendar month boundaries. Include year in the month key so different years cannot merge.', 'date', 'customer|first date|last date|month', 'grouped date extrema|partitioned extrema windows'),
 S(45, 'For each employee with dated shipments show the median calendar-day order-to-shipment delay, rounded to two decimals.',
   "WITH observations AS (SELECT `Employee ID` employee_id,`Order ID` order_id,DATEDIFF(`Shipped Date`,`Order Date`) delay_days FROM orders WHERE `Shipped Date` IS NOT NULL AND `Order Date` IS NOT NULL), numbered AS (SELECT employee_id,delay_days,ROW_NUMBER() OVER (PARTITION BY employee_id ORDER BY delay_days,order_id) position,COUNT(*) OVER (PARTITION BY employee_id) quantity FROM observations) SELECT employee_id,ROUND(AVG(delay_days),2) FROM numbered WHERE position IN ((quantity+1) DIV 2,(quantity+2) DIV 2) GROUP BY employee_id;",
   "WITH observations AS (SELECT `Employee ID` employee_id,`Order ID` order_id,DATEDIFF(`Shipped Date`,`Order Date`) delay_days FROM orders WHERE `Shipped Date` IS NOT NULL AND `Order Date` IS NOT NULL), numbered AS (SELECT current_observation.*,(SELECT COUNT(*) FROM observations peer WHERE peer.employee_id<=>current_observation.employee_id AND (peer.delay_days,peer.order_id)<=(current_observation.delay_days,current_observation.order_id)) position,(SELECT COUNT(*) FROM observations peer WHERE peer.employee_id<=>current_observation.employee_id) quantity FROM observations current_observation) SELECT employee_id,ROUND(AVG(delay_days),2) FROM numbered WHERE position IN ((quantity+1) DIV 2,(quantity+2) DIV 2) GROUP BY employee_id;",
   'Median retains duplicate order delays and averages the two central observations for even counts. Unshipped or undated orders are excluded, not given zero delay; delays use calendar dates.', 'date', 'employee|median shipment delay|calendar days', 'window order statistics|correlated order statistics'),
 S(46, 'Count customers by lowercase trimmed email domain, excluding NULL addresses, empty local parts, missing @ and empty domains.',
   "SELECT LOWER(TRIM(SUBSTRING_INDEX(`E-mail Address`,'@',-1))), COUNT(*) FROM customers WHERE `E-mail Address` IS NOT NULL AND LOCATE('@',`E-mail Address`)>1 AND CHAR_LENGTH(TRIM(SUBSTRING_INDEX(`E-mail Address`,'@',-1)))>0 GROUP BY LOWER(TRIM(SUBSTRING_INDEX(`E-mail Address`,'@',-1)));",
   "WITH domains AS (SELECT LOWER(TRIM(REGEXP_SUBSTR(`E-mail Address`,'[^@]+$'))) domain FROM customers WHERE `E-mail Address` REGEXP '^[^@]+@' AND TRIM(SUBSTRING_INDEX(`E-mail Address`,'@',-1))<>'') SELECT DISTINCT domain, COUNT(*) OVER (PARTITION BY domain) FROM domains;",
   'Domain means text after the final @; this is a teaching extraction rule, not full RFC address validation. All customer emails are NULL in this dump, so this deliberately tests an empty result; REGEXP_SUBSTR is available in 8.0.28.', 'string_funcs', 'customer|email domain|lowercase', 'SUBSTRING_INDEX grouped extraction|regular expression and window'),
 S(47, 'Return customer ID and a display name formatted Last Name, First Name, omitting the separator when either name is NULL or empty.',
   "SELECT ID, CONCAT_WS(', ',NULLIF(`Last Name`,''),NULLIF(`First Name`,'')) FROM customers;",
   "SELECT ID, CASE WHEN COALESCE(`Last Name`,'')='' THEN COALESCE(`First Name`,'') WHEN COALESCE(`First Name`,'')='' THEN `Last Name` ELSE CONCAT(`Last Name`,', ',`First Name`) END FROM customers;",
   'Empty strings and NULL names are omitted, not rendered as literal NULL. Whitespace-only names are preserved; both missing yields an empty display string.', 'string_funcs', 'customer|display name|concat_ws|null', 'CONCAT_WS NULLIF|CASE concatenation'),
 S(48, 'Find products whose trailing numeric Product Code suffix differs from ID; return ID, code and numeric suffix, considering only codes ending in hyphen and digits.',
   "SELECT ID,`Product Code`,CAST(SUBSTRING_INDEX(`Product Code`,'-',-1) AS UNSIGNED) FROM products WHERE `Product Code` REGEXP '-[0-9]+$' AND CAST(SUBSTRING_INDEX(`Product Code`,'-',-1) AS UNSIGNED)<>ID;",
   "WITH codes AS (SELECT ID,`Product Code`,REGEXP_SUBSTR(`Product Code`,'[0-9]+$')+0 suffix FROM products WHERE REGEXP_LIKE(`Product Code`,'-[0-9]+$')) SELECT ID,`Product Code`,suffix FROM codes WHERE suffix<>ID;",
   'A differing suffix is a catalogue diagnostic, not a declared integrity violation: Product Code is not the primary key and is not unique. Malformed or missing suffixes are excluded rather than cast to zero.', 'string_funcs', 'product code|numeric suffix|ID mismatch', 'delimiter extraction and CAST|regex extraction CTE'),
 S(49, 'Return product ID and the final space-delimited word of the trimmed Product Name, preserving NULL and returning empty text for all-space names.',
   "SELECT ID,SUBSTRING_INDEX(TRIM(`Product Name`),' ',-1) FROM products;",
   "SELECT ID,CASE WHEN `Product Name` IS NULL THEN NULL ELSE COALESCE(REGEXP_SUBSTR(TRIM(`Product Name`),'[^ ]+$'),'') END FROM products;",
   'Words are separated by ASCII spaces only; punctuation stays in the final word. TRIM removes surrounding spaces, not tabs; NULL is distinct from an empty cleaned name.', 'string_funcs', 'product name|last word|trim', 'SUBSTRING_INDEX|anchored regular expression'),
 S(50, 'Return customer ID and Business Phone with parentheses, ASCII spaces, dots and hyphens removed; preserve other characters and NULL.',
   "SELECT ID, REGEXP_REPLACE(`Business Phone`,'[() .-]','') FROM customers;",
   "SELECT ID, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`Business Phone`,'(',''),')',''),' ',''),'.',''),'-','') FROM customers;",
   'This removes exactly the five named characters; it is not an international phone parser. Plus signs, extension letters and other whitespace remain unchanged.', 'string_funcs', 'customer|phone|replace|regexp_replace', 'regex character class|nested literal replacements'),
 S(51, 'Find customers who ordered every product ordered by customer ID 1; additional products are allowed. Return customer ID and company.',
   "SELECT customer.ID, customer.Company FROM customers customer WHERE NOT EXISTS (SELECT 1 FROM orders reference_order JOIN `order details` required_line ON required_line.`Order ID`=reference_order.`Order ID` WHERE reference_order.`Customer ID`=1 AND NOT EXISTS (SELECT 1 FROM orders own_order JOIN `order details` own_line ON own_line.`Order ID`=own_order.`Order ID` WHERE own_order.`Customer ID`=customer.ID AND own_line.`Product ID`=required_line.`Product ID`));",
   "WITH required_products AS (SELECT DISTINCT line.`Product ID` product_id FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` WHERE ord.`Customer ID`=1), coverage AS (SELECT ord.`Customer ID` customer_id, COUNT(DISTINCT line.`Product ID`) quantity FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` JOIN required_products required_product ON required_product.product_id=line.`Product ID` GROUP BY ord.`Customer ID`) SELECT customer.ID, customer.Company FROM customers customer LEFT JOIN coverage ON coverage.customer_id=customer.ID WHERE COALESCE(coverage.quantity,0)=(SELECT COUNT(*) FROM required_products);",
   'Division uses the distinct reference product set, not quantities or order counts. Customer 1 is eligible too. If the reference set is empty every customer qualifies, including those without orders.', 'division', 'customer|every product|reference customer', 'double NOT EXISTS|coverage cardinality'),
 S(52, 'Return shippers that served every non-NULL Ship City served by shipper ID 1, allowing additional cities; show ID and company.',
   "SELECT shipper.ID, shipper.Company FROM shippers shipper WHERE NOT EXISTS (SELECT 1 FROM orders reference_order WHERE reference_order.`Shipper ID`=1 AND reference_order.`Ship City` IS NOT NULL AND NOT EXISTS (SELECT 1 FROM orders own_order WHERE own_order.`Shipper ID`=shipper.ID AND own_order.`Ship City`=reference_order.`Ship City`));",
   "WITH required_cities AS (SELECT DISTINCT `Ship City` city FROM orders WHERE `Shipper ID`=1 AND `Ship City` IS NOT NULL) SELECT shipper.ID, shipper.Company FROM shippers shipper LEFT JOIN orders ord ON ord.`Shipper ID`=shipper.ID LEFT JOIN required_cities required_city ON required_city.city=ord.`Ship City` GROUP BY shipper.ID, shipper.Company HAVING COUNT(DISTINCT required_city.city)=(SELECT COUNT(*) FROM required_cities);",
   'Served here means an order assigned to the shipper, not necessarily a non-NULL shipment date. NULL cities are excluded from the reference set; an empty set is satisfied vacuously.', 'division', 'shipper|every city|reference shipper', 'double NOT EXISTS|outer-join HAVING distinct coverage'),
 S(53, 'Find suppliers whose purchase history covers every product on the lowest numbered purchase order with details; return supplier ID/company.',
   "SELECT supplier.ID, supplier.Company FROM suppliers supplier WHERE NOT EXISTS (SELECT 1 FROM `purchase order details` required_line WHERE required_line.`Purchase Order ID`=(SELECT MIN(`Purchase Order ID`) FROM `purchase order details`) AND NOT EXISTS (SELECT 1 FROM `purchase orders` purchase JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` WHERE purchase.`Supplier ID`=supplier.ID AND detail.`Product ID`=required_line.`Product ID`));",
   "WITH required_products AS (SELECT DISTINCT `Product ID` product_id FROM `purchase order details` WHERE `Purchase Order ID`=(SELECT MIN(`Purchase Order ID`) FROM `purchase order details`)) SELECT supplier.ID, supplier.Company FROM suppliers supplier LEFT JOIN `purchase orders` purchase ON purchase.`Supplier ID`=supplier.ID LEFT JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` LEFT JOIN required_products required_product ON required_product.product_id=detail.`Product ID` GROUP BY supplier.ID, supplier.Company HAVING COUNT(DISTINCT required_product.product_id)=(SELECT COUNT(*) FROM required_products);",
   'Coverage spans all purchase orders for the supplier; receipt and payment do not matter. The lowest ID is chosen from detail-bearing orders. Extra products are allowed; empty required set qualifies every supplier.', 'division', 'supplier|every product|purchase history', 'double anti-subquery|distinct coverage HAVING'),
 S(54, 'Find orders containing every product on the lowest numbered order with details, allowing extras; return order IDs.',
   "SELECT ord.`Order ID` FROM orders ord WHERE NOT EXISTS (SELECT 1 FROM `order details` required_line WHERE required_line.`Order ID`=(SELECT MIN(`Order ID`) FROM `order details`) AND NOT EXISTS (SELECT 1 FROM `order details` own_line WHERE own_line.`Order ID`=ord.`Order ID` AND own_line.`Product ID`=required_line.`Product ID`));",
   "WITH required_products AS (SELECT DISTINCT `Product ID` product_id FROM `order details` WHERE `Order ID`=(SELECT MIN(`Order ID`) FROM `order details`)) SELECT ord.`Order ID` FROM orders ord LEFT JOIN `order details` line ON line.`Order ID`=ord.`Order ID` LEFT JOIN required_products required_product ON required_product.product_id=line.`Product ID` GROUP BY ord.`Order ID` HAVING COUNT(DISTINCT required_product.product_id)=(SELECT COUNT(*) FROM required_products);",
   'This is set containment, not equality: extra products and larger quantities are allowed. Include the reference order itself; an empty reference set would qualify every order.', 'division', 'orders|every product|reference order', 'double NOT EXISTS|distinct-count division'),
 S(55, 'Return product ID and standard cost where that cost is greater than ALL non-NULL standard costs in category Seafood; keep empty-set semantics.',
   "SELECT ID, `Standard Cost` FROM products WHERE `Standard Cost`>ALL (SELECT `Standard Cost` FROM products WHERE Category='Seafood' AND `Standard Cost` IS NOT NULL);",
   "SELECT product.ID, product.`Standard Cost` FROM products product WHERE NOT EXISTS (SELECT 1 FROM products seafood WHERE seafood.Category='Seafood' AND seafood.`Standard Cost` IS NOT NULL) OR (product.`Standard Cost` IS NOT NULL AND NOT EXISTS (SELECT 1 FROM products seafood WHERE seafood.Category='Seafood' AND seafood.`Standard Cost`>=product.`Standard Cost`));",
   'Seafood is absent from this dump: > ALL over an empty set is TRUE, even for a NULL left operand. The alternative explicitly handles that case; replacing ALL by MAX alone would be wrong.', 'all_any', 'standard cost|Seafood|greater than all|empty set', 'quantified ALL|anti-existence with empty-set branch'),
 S(56, 'Return product ID and standard cost where that cost is greater than ANY non-NULL standard cost in category Seafood.',
   "SELECT ID, `Standard Cost` FROM products WHERE `Standard Cost`>ANY (SELECT `Standard Cost` FROM products WHERE Category='Seafood' AND `Standard Cost` IS NOT NULL);",
   "SELECT product.ID, product.`Standard Cost` FROM products product WHERE EXISTS (SELECT 1 FROM products seafood WHERE seafood.Category='Seafood' AND seafood.`Standard Cost`<product.`Standard Cost`);",
   'ANY means at least one true comparison. Seafood is absent here, so this deliberate companion to ALL returns no rows; verification.empty must remain true. NULL reference costs are excluded explicitly.', 'all_any', 'standard cost|Seafood|greater than any|empty set', 'quantified ANY|correlated EXISTS'),
 S(57, 'Find orders whose Shipping Fee exceeds the average Shipping Fee of that same customer; return customer ID, order ID, fee and customer average rounded to cents.',
   "SELECT ord.`Customer ID`, ord.`Order ID`, ord.`Shipping Fee`, ROUND((SELECT AVG(peer.`Shipping Fee`) FROM orders peer WHERE peer.`Customer ID`<=>ord.`Customer ID`),2) FROM orders ord WHERE ord.`Shipping Fee`>(SELECT AVG(peer.`Shipping Fee`) FROM orders peer WHERE peer.`Customer ID`<=>ord.`Customer ID`);",
   "SELECT `Customer ID`, `Order ID`, `Shipping Fee`, ROUND(average_fee,2) FROM (SELECT `Customer ID`, `Order ID`, `Shipping Fee`, AVG(`Shipping Fee`) OVER (PARTITION BY `Customer ID`) average_fee FROM orders) scored WHERE `Shipping Fee`>average_fee;",
   'Compare with the unrounded customer-specific average including the current order. AVG ignores NULL fees; NULL fees themselves cannot pass the strict comparison.', 'correlated', 'customer|shipping fee|above own average', 'correlated AVG|partitioned AVG window'),
 S(58, 'Find orders with gross line totals above their employee own average order gross total; show employee ID, order ID and gross total rounded to cents.',
   "WITH totals AS (SELECT ord.`Employee ID` employee_id, ord.`Order ID` order_id, SUM(line.Quantity*line.`Unit Price`) gross FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` GROUP BY ord.`Employee ID`,ord.`Order ID`) SELECT employee_id,order_id,ROUND(gross,2) FROM totals current_total WHERE gross>(SELECT AVG(peer.gross) FROM totals peer WHERE peer.employee_id<=>current_total.employee_id);",
   "WITH totals AS (SELECT ord.`Employee ID` employee_id, ord.`Order ID` order_id, SUM(line.Quantity*line.`Unit Price`) gross FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` GROUP BY ord.`Employee ID`,ord.`Order ID`), scored AS (SELECT totals.*, AVG(gross) OVER (PARTITION BY employee_id) employee_average FROM totals) SELECT employee_id,order_id,ROUND(gross,2) FROM scored WHERE gross>employee_average;",
   'Only orders with detail lines are observations. Compute the average of order totals, not the average detail value; gross excludes Discount and header charges.', 'correlated', 'employee|above average|order gross', 'correlated average of totals|window average of totals'),
 S(59, 'Return product ID, category, standard cost and category average cost for products above their own category average standard cost.',
   "SELECT product.ID, product.Category, product.`Standard Cost`, ROUND((SELECT AVG(peer.`Standard Cost`) FROM products peer WHERE peer.Category<=>product.Category),4) FROM products product WHERE product.`Standard Cost`>(SELECT AVG(peer.`Standard Cost`) FROM products peer WHERE peer.Category<=>product.Category);",
   "SELECT ID,Category,`Standard Cost`,ROUND(average_cost,4) FROM (SELECT ID,Category,`Standard Cost`,AVG(`Standard Cost`) OVER (PARTITION BY Category) average_cost FROM products) scored WHERE `Standard Cost`>average_cost;",
   'This asks about Standard Cost, not List Price. Comparison uses the unrounded average including the current product; NULL costs are ignored by AVG and excluded by the predicate.', 'correlated', 'standard cost|category average|above', 'correlated AVG|window AVG'),
 S(60, 'Return orders with at least one detail line where every detail Discount equals zero; NULL discounts must disqualify an order.',
   "SELECT ord.`Order ID` FROM orders ord WHERE EXISTS (SELECT 1 FROM `order details` line WHERE line.`Order ID`=ord.`Order ID`) AND NOT EXISTS (SELECT 1 FROM `order details` line WHERE line.`Order ID`=ord.`Order ID` AND (line.Discount IS NULL OR line.Discount<>0));",
   "SELECT `Order ID` FROM `order details` GROUP BY `Order ID` HAVING COUNT(*)=SUM(CASE WHEN Discount=0 THEN 1 ELSE 0 END);",
   'Unlike vacuous relational division, this explicitly requires a nonempty order. NULL is not a zero discount; COUNT(*) equals the count of known zero-discount lines only when all lines qualify.', 'division', 'orders|every line|zero discount|null', 'EXISTS plus anti-counterexample|conditional HAVING'),
 S(61, 'For each purchase order show item cost subtotal and grand total including its Shipping Fee and Taxes, rounded to cents, with empty orders at zero subtotal.',
   "SELECT purchase.`Purchase Order ID`, ROUND(COALESCE(SUM(detail.Quantity*detail.`Unit Cost`),0),2), ROUND(COALESCE(SUM(detail.Quantity*detail.`Unit Cost`),0)+COALESCE(purchase.`Shipping Fee`,0)+COALESCE(purchase.Taxes,0),2) FROM `purchase orders` purchase LEFT JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` GROUP BY purchase.`Purchase Order ID`,purchase.`Shipping Fee`,purchase.Taxes;",
   "SELECT purchase.`Purchase Order ID`, ROUND(COALESCE((SELECT SUM(detail.Quantity*detail.`Unit Cost`) FROM `purchase order details` detail WHERE detail.`Purchase Order ID`=purchase.`Purchase Order ID`),0),2), ROUND(COALESCE((SELECT SUM(detail.Quantity*detail.`Unit Cost`) FROM `purchase order details` detail WHERE detail.`Purchase Order ID`=purchase.`Purchase Order ID`),0)+COALESCE(purchase.`Shipping Fee`,0)+COALESCE(purchase.Taxes,0),2) FROM `purchase orders` purchase;",
   'Add each header charge once after the line sum. Missing charges are treated as zero; the calculation is a purchase-order estimate, not the Payment Amount.', 'computed', 'purchase order|subtotal|grand total|tax', 'outer aggregation|correlated line subtotal'),
 S(62, 'List purchase detail IDs where Unit Cost exceeds the current product Standard Cost, with product ID and both costs.',
   "SELECT detail.ID, product.ID, detail.`Unit Cost`, product.`Standard Cost` FROM `purchase order details` detail JOIN products product ON product.ID=detail.`Product ID` WHERE detail.`Unit Cost`>product.`Standard Cost`;",
   "SELECT detail.ID,detail.`Product ID`,detail.`Unit Cost`,(SELECT product.`Standard Cost` FROM products product WHERE product.ID=detail.`Product ID`) FROM `purchase order details` detail WHERE EXISTS (SELECT 1 FROM products product WHERE product.ID=detail.`Product ID` AND detail.`Unit Cost`>product.`Standard Cost`);",
   'Compare historical procurement unit cost against the current standard cost, without interpreting the difference as historical profit. NULL costs cannot satisfy >.', 'inner_join', 'purchase detail|unit cost|standard cost', 'filtered join|EXISTS and scalar cost'),
 S(63, 'For each purchase order with receipts show latest detail receipt date and calendar days from Creation Date to that receipt.',
   "SELECT purchase.`Purchase Order ID`, MAX(detail.`Date Received`), DATEDIFF(MAX(detail.`Date Received`),purchase.`Creation Date`) FROM `purchase orders` purchase JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` WHERE detail.`Date Received` IS NOT NULL GROUP BY purchase.`Purchase Order ID`,purchase.`Creation Date`;",
   "SELECT DISTINCT purchase.`Purchase Order ID`, MAX(detail.`Date Received`) OVER (PARTITION BY purchase.`Purchase Order ID`), DATEDIFF(MAX(detail.`Date Received`) OVER (PARTITION BY purchase.`Purchase Order ID`),purchase.`Creation Date`) FROM `purchase orders` purchase JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` WHERE detail.`Date Received` IS NOT NULL;",
   'Latest refers to the greatest recorded receipt date, not the largest detail ID. It is not a completion date when other lines remain unreceived; NULL Creation Date would yield NULL delay.', 'date', 'purchase order|latest receipt|calendar days', 'grouped MAX|MAX window'),
 S(64, 'Show every supplier with total ordered purchase quantity and quantity on received purchase details; use zeros for suppliers without lines.',
   "SELECT supplier.ID, COALESCE(SUM(detail.Quantity),0), COALESCE(SUM(CASE WHEN detail.`Date Received` IS NOT NULL THEN detail.Quantity ELSE 0 END),0) FROM suppliers supplier LEFT JOIN `purchase orders` purchase ON purchase.`Supplier ID`=supplier.ID LEFT JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` GROUP BY supplier.ID;",
   "SELECT supplier.ID, COALESCE((SELECT SUM(detail.Quantity) FROM `purchase orders` purchase JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` WHERE purchase.`Supplier ID`=supplier.ID),0), COALESCE((SELECT SUM(detail.Quantity) FROM `purchase orders` purchase JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` WHERE purchase.`Supplier ID`=supplier.ID AND detail.`Date Received` IS NOT NULL),0) FROM suppliers supplier;",
   'NULL quantities are ignored, and all-unknown or missing totals display zero. Received quantity means the full Quantity of each line with a receipt date; the schema has no separate partial-receipt quantity column. Do not infer receipt from Posted To Inventory.', 'cond_agg', 'supplier|ordered quantity|received quantity', 'conditional outer sums|separate correlated sums'),
 S(65, 'Which products were procured from at least two distinct suppliers? Return product ID/name and supplier count using purchase history.',
   "SELECT product.ID,product.`Product Name`,COUNT(DISTINCT purchase.`Supplier ID`) FROM products product JOIN `purchase order details` detail ON detail.`Product ID`=product.ID JOIN `purchase orders` purchase ON purchase.`Purchase Order ID`=detail.`Purchase Order ID` GROUP BY product.ID,product.`Product Name` HAVING COUNT(DISTINCT purchase.`Supplier ID`)>=2;",
   "WITH pairs AS (SELECT DISTINCT detail.`Product ID` product_id,purchase.`Supplier ID` supplier_id FROM `purchase order details` detail JOIN `purchase orders` purchase ON purchase.`Purchase Order ID`=detail.`Purchase Order ID` WHERE purchase.`Supplier ID` IS NOT NULL), scored AS (SELECT product_id,COUNT(*) OVER (PARTITION BY product_id) quantity FROM pairs) SELECT DISTINCT product.ID,product.`Product Name`,scored.quantity FROM scored JOIN products product ON product.ID=scored.product_id WHERE scored.quantity>=2;",
   'Actual purchase headers establish supplier history, not the text Supplier IDs catalogue field. Repeat purchases from one supplier count once; unknown supplier IDs are excluded.', 'group_having', 'product|at least two suppliers|purchase history', 'HAVING COUNT DISTINCT|deduplicated window'),
 S(66, 'Show purchase order ID, calculated grand total, Payment Amount and remaining balance, with missing payments treated as zero.',
   "SELECT purchase.`Purchase Order ID`, ROUND(COALESCE(SUM(detail.Quantity*detail.`Unit Cost`),0)+COALESCE(purchase.`Shipping Fee`,0)+COALESCE(purchase.Taxes,0),2), COALESCE(purchase.`Payment Amount`,0), ROUND(COALESCE(SUM(detail.Quantity*detail.`Unit Cost`),0)+COALESCE(purchase.`Shipping Fee`,0)+COALESCE(purchase.Taxes,0)-COALESCE(purchase.`Payment Amount`,0),2) FROM `purchase orders` purchase LEFT JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` GROUP BY purchase.`Purchase Order ID`,purchase.`Shipping Fee`,purchase.Taxes,purchase.`Payment Amount`;",
   "WITH balances AS (SELECT purchase.`Purchase Order ID` purchase_id,COALESCE((SELECT SUM(detail.Quantity*detail.`Unit Cost`) FROM `purchase order details` detail WHERE detail.`Purchase Order ID`=purchase.`Purchase Order ID`),0)+COALESCE(purchase.`Shipping Fee`,0)+COALESCE(purchase.Taxes,0) gross,COALESCE(purchase.`Payment Amount`,0) paid FROM `purchase orders` purchase) SELECT purchase_id,ROUND(gross,2),paid,ROUND(gross-paid,2) FROM balances;",
   'Remaining balance is computed, not read as a stored debt; negative values indicate overpayment under this formula. Header tax and shipping are added only once; rounding occurs at the end.', 'computed', 'purchase order|payment|remaining balance', 'outer aggregate balance|correlated subtotal CTE'),
 S(67, 'For each product on purchase details show ordered quantity and percentage of that quantity on received lines, rounded to two decimals.',
   "SELECT `Product ID`,SUM(Quantity),ROUND(100*SUM(CASE WHEN `Date Received` IS NOT NULL THEN Quantity ELSE 0 END)/NULLIF(SUM(Quantity),0),2) FROM `purchase order details` GROUP BY `Product ID`;",
   "SELECT DISTINCT `Product ID`,SUM(Quantity) OVER (PARTITION BY `Product ID`),ROUND(100*SUM(CASE WHEN `Date Received` IS NOT NULL THEN Quantity ELSE 0 END) OVER (PARTITION BY `Product ID`)/NULLIF(SUM(Quantity) OVER (PARTITION BY `Product ID`),0),2) FROM `purchase order details`;",
   'Weight receipt rate by quantity, not by number of lines. Treat a dated line as fully received because partial quantities are not represented; a zero ordered quantity yields NULL percentage.', 'computed', 'purchase quantity|receipt percentage|product', 'grouped conditional ratio|window conditional ratio'),
 S(68, 'List purchase orders created and approved by different employees, showing purchase order ID and the creator and approver last names.',
   "SELECT purchase.`Purchase Order ID`,creator.`Last Name`,approver.`Last Name` FROM `purchase orders` purchase JOIN employees creator ON creator.ID=purchase.`Created By` JOIN employees approver ON approver.ID=purchase.`Approved By` WHERE creator.ID<>approver.ID;",
   "SELECT purchase.`Purchase Order ID`,(SELECT employee.`Last Name` FROM employees employee WHERE employee.ID=purchase.`Created By`),(SELECT employee.`Last Name` FROM employees employee WHERE employee.ID=purchase.`Approved By`) FROM `purchase orders` purchase WHERE purchase.`Created By`<>purchase.`Approved By` AND EXISTS (SELECT 1 FROM employees employee WHERE employee.ID=purchase.`Created By`) AND EXISTS (SELECT 1 FROM employees employee WHERE employee.ID=purchase.`Approved By`);",
   'Different employee IDs, not different name strings, establish separation of duties. Unapproved or unresolved employee links do not qualify.', 'self_join', 'purchase order|creator|approver|different employee', 'two employee-role joins|scalar role lookups'),
 S(69, 'For each supplier/product purchase-history combination return quantity-weighted average Unit Cost rounded to four decimals, using only lines with known quantity and cost.',
   "SELECT purchase.`Supplier ID`,detail.`Product ID`,ROUND(SUM(detail.Quantity*detail.`Unit Cost`)/NULLIF(SUM(detail.Quantity),0),4) FROM `purchase orders` purchase JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` WHERE detail.Quantity IS NOT NULL AND detail.`Unit Cost` IS NOT NULL GROUP BY purchase.`Supplier ID`,detail.`Product ID`;",
   "WITH weighted AS (SELECT purchase.`Supplier ID` supplier_id,detail.`Product ID` product_id,SUM(detail.Quantity*detail.`Unit Cost`) OVER (PARTITION BY purchase.`Supplier ID`,detail.`Product ID`) total_cost,SUM(detail.Quantity) OVER (PARTITION BY purchase.`Supplier ID`,detail.`Product ID`) total_quantity FROM `purchase orders` purchase JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` WHERE detail.Quantity IS NOT NULL AND detail.`Unit Cost` IS NOT NULL) SELECT DISTINCT supplier_id,product_id,ROUND(total_cost/NULLIF(total_quantity,0),4) FROM weighted;",
   'Incomplete input lines are omitted from both sums. This is historical average procurement cost weighted by units, not AVG(Unit Cost). Zero total quantity produces NULL; all purchase details count regardless of receipt.', 'computed', 'supplier|product|weighted unit cost', 'grouped weighted average|window weighted average'),
 S(70, 'Return approved purchase order IDs with full elapsed hours from Submitted Date to Approved Date, retaining negative intervals.',
   "SELECT `Purchase Order ID`,TIMESTAMPDIFF(HOUR,`Submitted Date`,`Approved Date`) FROM `purchase orders` WHERE `Submitted Date` IS NOT NULL AND `Approved Date` IS NOT NULL;",
   "SELECT `Purchase Order ID`,TRUNCATE(TIMESTAMPDIFF(SECOND,`Submitted Date`,`Approved Date`)/3600,0) FROM `purchase orders` WHERE `Purchase Order ID` IN (SELECT `Purchase Order ID` FROM `purchase orders` WHERE `Submitted Date` IS NOT NULL AND `Approved Date` IS NOT NULL);",
   'Full elapsed hours truncate toward zero; negative intervals are evidence of recorded dates, not silently clamped. Non-NULL approval date defines the included set, not status text.', 'date', 'purchase approval|submitted date|elapsed hours', 'TIMESTAMPDIFF hours|seconds conversion with truncation'),
 S(71, 'For each linked invoice show Invoice ID, invoice Shipping, order Shipping Fee and invoice-minus-order shipping difference.',
   "SELECT invoice.`Invoice ID`,invoice.Shipping,ord.`Shipping Fee`,invoice.Shipping-ord.`Shipping Fee` FROM invoices invoice JOIN orders ord ON ord.`Order ID`=invoice.`Order ID`;",
   "SELECT invoice.`Invoice ID`,invoice.Shipping,(SELECT ord.`Shipping Fee` FROM orders ord WHERE ord.`Order ID`=invoice.`Order ID`),invoice.Shipping-(SELECT ord.`Shipping Fee` FROM orders ord WHERE ord.`Order ID`=invoice.`Order ID`) FROM invoices invoice WHERE EXISTS (SELECT 1 FROM orders ord WHERE ord.`Order ID`=invoice.`Order ID`);",
   'Return all linked invoices, including equal charges, so comparison does not become an empty mismatch-only exercise. Unknown charges produce NULL difference, not zero.', 'computed', 'invoice|shipping difference|order fee', 'join arithmetic|scalar header lookups'),
 S(72, 'For each linked invoice compare invoice Tax with order Taxes and show the signed tax difference, returning invoice ID and both amounts.',
   "SELECT invoice.`Invoice ID`,invoice.Tax,ord.Taxes,invoice.Tax-ord.Taxes FROM invoices invoice JOIN orders ord ON ord.`Order ID`=invoice.`Order ID`;",
   "SELECT invoice.`Invoice ID`,invoice.Tax,(SELECT ord.Taxes FROM orders ord WHERE ord.`Order ID`=invoice.`Order ID`),invoice.Tax-(SELECT ord.Taxes FROM orders ord WHERE ord.`Order ID`=invoice.`Order ID`) FROM invoices invoice WHERE invoice.`Order ID` IN (SELECT `Order ID` FROM orders);",
   'Invoice Tax and order Taxes are distinct stored fields. Do not multiply the order Tax Rate by an assumed base; NULL amounts remain unknown.', 'computed', 'invoice|tax difference|order taxes', 'joined comparison|scalar tax subquery'),
 S(73, 'Group invoices by Invoice Date year-month and show invoice count and summed Amount Due rounded to cents, excluding undated invoices.',
   "SELECT DATE_FORMAT(`Invoice Date`,'%Y-%m'),COUNT(*),ROUND(SUM(`Amount Due`),2) FROM invoices WHERE `Invoice Date` IS NOT NULL GROUP BY DATE_FORMAT(`Invoice Date`,'%Y-%m');",
   "SELECT DISTINCT DATE_FORMAT(`Invoice Date`,'%Y-%m'),COUNT(*) OVER (PARTITION BY YEAR(`Invoice Date`),MONTH(`Invoice Date`)),ROUND(SUM(`Amount Due`) OVER (PARTITION BY YEAR(`Invoice Date`),MONTH(`Invoice Date`)),2) FROM invoices WHERE `Invoice Date` IS NOT NULL;",
   'Bucket by Invoice Date, not Order Date or Due Date. Amount Due is summed as stored and is not assumed equal to a computed line subtotal.', 'date', 'invoice month|amount due|count', 'grouped invoice month|partitioned month windows'),
 S(74, 'Show every customer with invoice count, summed invoice Tax, Shipping and Amount Due, using zero when no invoice contributes.',
   "SELECT customer.ID,COUNT(invoice.`Invoice ID`),ROUND(COALESCE(SUM(invoice.Tax),0),2),ROUND(COALESCE(SUM(invoice.Shipping),0),2),ROUND(COALESCE(SUM(invoice.`Amount Due`),0),2) FROM customers customer LEFT JOIN orders ord ON ord.`Customer ID`=customer.ID LEFT JOIN invoices invoice ON invoice.`Order ID`=ord.`Order ID` GROUP BY customer.ID;",
   "WITH totals AS (SELECT ord.`Customer ID` customer_id,COUNT(*) quantity,SUM(invoice.Tax) tax,SUM(invoice.Shipping) shipping,SUM(invoice.`Amount Due`) due FROM orders ord JOIN invoices invoice ON invoice.`Order ID`=ord.`Order ID` GROUP BY ord.`Customer ID`) SELECT customer.ID,COALESCE(totals.quantity,0),ROUND(COALESCE(totals.tax,0),2),ROUND(COALESCE(totals.shipping,0),2),ROUND(COALESCE(totals.due,0),2) FROM customers customer LEFT JOIN totals ON totals.customer_id=customer.ID;",
   'Keep customers without invoices. Join no detail table: otherwise invoice money would be duplicated by order-line fanout. NULL aggregate totals are deliberately displayed as zero.', 'left_join', 'customer|invoice totals|zero invoices', 'outer chain aggregate|invoice preaggregation'),
 S(75, 'Number invoices within each order by Invoice Date then Invoice ID, returning order ID, invoice ID and ordinal, including undated invoices first.',
   "SELECT `Order ID`,`Invoice ID`,ROW_NUMBER() OVER (PARTITION BY `Order ID` ORDER BY `Invoice Date`,`Invoice ID`) FROM invoices;",
   "SELECT invoice.`Order ID`,invoice.`Invoice ID`,1+(SELECT COUNT(*) FROM invoices prior WHERE prior.`Order ID`<=>invoice.`Order ID` AND (COALESCE(prior.`Invoice Date`,'1000-01-01'),prior.`Invoice ID`)<(COALESCE(invoice.`Invoice Date`,'1000-01-01'),invoice.`Invoice ID`)) FROM invoices invoice;",
   'Each invoice receives a unique ordinal, not a dense date rank. NULL dates sort first; ID provides deterministic ordering for equal dates. Orders without invoices have no rows.', 'topn_rank', 'invoice|order|ordinal|row number', 'ROW_NUMBER|correlated predecessor count'),
 S(76, 'Return every customer invoice tied at that customer earliest non-NULL Invoice Date, showing customer ID, invoice ID and date.',
   "SELECT customer_id,invoice_id,invoice_date FROM (SELECT ord.`Customer ID` customer_id,invoice.`Invoice ID` invoice_id,invoice.`Invoice Date` invoice_date,DENSE_RANK() OVER (PARTITION BY ord.`Customer ID` ORDER BY invoice.`Invoice Date`) position FROM invoices invoice JOIN orders ord ON ord.`Order ID`=invoice.`Order ID` WHERE invoice.`Invoice Date` IS NOT NULL) ranked WHERE position=1;",
   "SELECT ord.`Customer ID`,invoice.`Invoice ID`,invoice.`Invoice Date` FROM invoices invoice JOIN orders ord ON ord.`Order ID`=invoice.`Order ID` WHERE invoice.`Invoice Date`=(SELECT MIN(earlier.`Invoice Date`) FROM invoices earlier JOIN orders peer ON peer.`Order ID`=earlier.`Order ID` WHERE peer.`Customer ID`<=>ord.`Customer ID`);",
   'All invoices at the minimum timestamp survive; unlike the single-invoice selection, ID does not break these ties. NULL dates are ignored.', 'topn_rank', 'customer|earliest invoices|include ties', 'DENSE_RANK|correlated MIN'),
 S(77, 'Return order IDs and customer companies for orders already invoiced but still missing Shipped Date, once per order.',
   "SELECT ord.`Order ID`,customer.Company FROM orders ord JOIN customers customer ON customer.ID=ord.`Customer ID` WHERE ord.`Shipped Date` IS NULL AND EXISTS (SELECT 1 FROM invoices invoice WHERE invoice.`Order ID`=ord.`Order ID`);",
   "SELECT DISTINCT ord.`Order ID`,customer.Company FROM orders ord JOIN customers customer ON customer.ID=ord.`Customer ID` JOIN invoices invoice ON invoice.`Order ID`=ord.`Order ID` WHERE ord.`Shipped Date` IS NULL;",
   'Invoiced is existence of an invoice, not Paid Date or Amount Due. DISTINCT in the join alternative prevents multiple invoices duplicating an order.', 'exists', 'invoiced|unshipped|customer', 'EXISTS|distinct invoice join'),
 S(78, 'Summarize invoices in one row: total count, missing Due Date count and known Due Date count.',
   "SELECT COUNT(*),COALESCE(SUM(CASE WHEN `Due Date` IS NULL THEN 1 ELSE 0 END),0),COUNT(`Due Date`) FROM invoices;",
   "SELECT (SELECT COUNT(*) FROM invoices),(SELECT COUNT(*) FROM invoices WHERE `Due Date` IS NULL),(SELECT COUNT(*) FROM invoices WHERE `Due Date` IS NOT NULL);",
   'Missing due dates are unknown, not overdue or paid. A single row of zeros is returned even for an empty invoice table; all Due Dates happen to be NULL in this dump.', 'null_handling', 'invoice|due date|missing count', 'conditional aggregate|separate scalar counts'),
 S(79, 'For each employee with dated invoices and orders show average calendar days from Order Date to Invoice Date, rounded to two decimals.',
   "SELECT ord.`Employee ID`,ROUND(AVG(DATEDIFF(invoice.`Invoice Date`,ord.`Order Date`)),2) FROM orders ord JOIN invoices invoice ON invoice.`Order ID`=ord.`Order ID` WHERE invoice.`Invoice Date` IS NOT NULL AND ord.`Order Date` IS NOT NULL GROUP BY ord.`Employee ID`;",
   "SELECT DISTINCT ord.`Employee ID`,ROUND(AVG(DATEDIFF(invoice.`Invoice Date`,ord.`Order Date`)) OVER (PARTITION BY ord.`Employee ID`),2) FROM orders ord JOIN invoices invoice ON invoice.`Order ID`=ord.`Order ID` WHERE invoice.`Invoice Date` IS NOT NULL AND ord.`Order Date` IS NOT NULL;",
   'The observation unit is invoice, so an order with multiple invoices contributes multiple delays. Negative recorded delays are preserved; calendar dates, not elapsed hours, are compared.', 'date', 'employee|invoice delay|average days', 'grouped average delay|window average delay'),
 S(80, 'For each invoice show discounted order-line subtotal and its difference from stored Amount Due, rounding final values to cents.',
   "SELECT invoice.`Invoice ID`,ROUND(COALESCE(totals.net,0),2),ROUND(COALESCE(totals.net,0)-invoice.`Amount Due`,2) FROM invoices invoice LEFT JOIN (SELECT `Order ID` order_id,SUM(Quantity*`Unit Price`*(1-Discount)) net FROM `order details` GROUP BY `Order ID`) totals ON totals.order_id=invoice.`Order ID`;",
   "SELECT invoice.`Invoice ID`,ROUND(COALESCE((SELECT SUM(line.Quantity*line.`Unit Price`*(1-line.Discount)) FROM `order details` line WHERE line.`Order ID`=invoice.`Order ID`),0),2),ROUND(COALESCE((SELECT SUM(line.Quantity*line.`Unit Price`*(1-line.Discount)) FROM `order details` line WHERE line.`Order ID`=invoice.`Order ID`),0)-invoice.`Amount Due`,2) FROM invoices invoice;",
   'This is a diagnostic comparison, not an asserted accounting identity: Amount Due may include other policy or be unpopulated. Shipping and tax are not added to the requested line subtotal; no lines means zero.', 'computed', 'invoice|net subtotal|amount due difference', 'preaggregated detail outer join|correlated line sums'),
 S(81, 'For each product appearing in sales details show ordered quantity, Sold inventory quantity and ordered-minus-Sold difference.',
   "WITH ordered AS (SELECT `Product ID` product_id,SUM(Quantity) quantity FROM `order details` GROUP BY `Product ID`), sold AS (SELECT movement.`Product ID` product_id,SUM(movement.Quantity) quantity FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE kind.`Type Name`='Sold' GROUP BY movement.`Product ID`) SELECT ordered.product_id,ordered.quantity,COALESCE(sold.quantity,0),ordered.quantity-COALESCE(sold.quantity,0) FROM ordered LEFT JOIN sold ON sold.product_id=ordered.product_id;",
   "SELECT line.`Product ID`,SUM(line.Quantity),COALESCE((SELECT SUM(movement.Quantity) FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE movement.`Product ID`=line.`Product ID` AND kind.`Type Name`='Sold'),0),SUM(line.Quantity)-COALESCE((SELECT SUM(movement.Quantity) FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE movement.`Product ID`=line.`Product ID` AND kind.`Type Name`='Sold'),0) FROM `order details` line GROUP BY line.`Product ID`;",
   'Aggregate the two independent child tables separately to avoid multiplication. This reports discrepancies, not proof of corrupt stock: order status, timing and opening balances differ.', 'computed', 'ordered quantity|Sold quantity|reconciliation', 'two preaggregated relations|correlated ledger aggregate'),
 S(82, 'For every product calculate net recorded inventory movement: Purchased positive, Sold and Waste negative, On Hold neutral.',
   "SELECT product.ID,COALESCE(SUM(CASE kind.`Type Name` WHEN 'Purchased' THEN movement.Quantity WHEN 'Sold' THEN -movement.Quantity WHEN 'Waste' THEN -movement.Quantity ELSE 0 END),0) FROM products product LEFT JOIN `inventory transactions` movement ON movement.`Product ID`=product.ID LEFT JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` GROUP BY product.ID;",
   "SELECT product.ID,COALESCE((SELECT SUM(movement.Quantity) FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE movement.`Product ID`=product.ID AND kind.`Type Name`='Purchased'),0)-COALESCE((SELECT SUM(movement.Quantity) FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE movement.`Product ID`=product.ID AND kind.`Type Name` IN ('Sold','Waste')),0) FROM products product;",
   'This is signed recorded movement, not guaranteed current stock: no opening balance is supplied. On Hold is a reservation and contributes zero; unrecognized type names also contribute zero.', 'cond_agg', 'inventory|net movement|Purchased|Sold|Waste', 'CASE signed aggregate|difference of independent sums'),
 S(83, 'Show every inventory movement tied at its product latest non-NULL Transaction Created Date, returning product ID, transaction ID and timestamp.',
   "SELECT `Product ID`,`Transaction ID`,`Transaction Created Date` FROM (SELECT `Product ID`,`Transaction ID`,`Transaction Created Date`,DENSE_RANK() OVER (PARTITION BY `Product ID` ORDER BY `Transaction Created Date` DESC) position FROM `inventory transactions` WHERE `Transaction Created Date` IS NOT NULL) ranked WHERE position=1;",
   "SELECT movement.`Product ID`,movement.`Transaction ID`,movement.`Transaction Created Date` FROM `inventory transactions` movement WHERE movement.`Transaction Created Date`=(SELECT MAX(peer.`Transaction Created Date`) FROM `inventory transactions` peer WHERE peer.`Product ID`<=>movement.`Product ID`);",
   'Latest means greatest creation timestamp across all transaction types, not modified timestamp or transaction ID. All tied timestamps survive; undated movements are excluded.', 'topn_rank', 'inventory|latest timestamp|include ties', 'DENSE_RANK|correlated MAX timestamp'),
 S(84, 'Count dated inventory transactions for each creation year-month and transaction type name.',
   "SELECT DATE_FORMAT(movement.`Transaction Created Date`,'%Y-%m'),kind.`Type Name`,COUNT(*) FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE movement.`Transaction Created Date` IS NOT NULL GROUP BY DATE_FORMAT(movement.`Transaction Created Date`,'%Y-%m'),kind.`Type Name`;",
   "SELECT DISTINCT DATE_FORMAT(movement.`Transaction Created Date`,'%Y-%m'),kind.`Type Name`,COUNT(*) OVER (PARTITION BY YEAR(movement.`Transaction Created Date`),MONTH(movement.`Transaction Created Date`),kind.`Type Name`) FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE movement.`Transaction Created Date` IS NOT NULL;",
   'Group counts, not quantities, using creation date rather than modification date. Include the year; missing type/month combinations are absent, not synthetic zeros.', 'date', 'inventory|monthly count|transaction type', 'grouped type-month|type-month window'),
 S(85, 'List Sold inventory transactions with valid products and optional customer order information, showing transaction ID, resolved order ID, customer ID and product name.',
   "SELECT movement.`Transaction ID`,ord.`Order ID`,ord.`Customer ID`,product.`Product Name` FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` LEFT JOIN orders ord ON ord.`Order ID`=movement.`Customer Order ID` JOIN products product ON product.ID=movement.`Product ID` WHERE kind.`Type Name`='Sold';",
   "SELECT movement.`Transaction ID`,(SELECT ord.`Order ID` FROM orders ord WHERE ord.`Order ID`=movement.`Customer Order ID`),(SELECT ord.`Customer ID` FROM orders ord WHERE ord.`Order ID`=movement.`Customer Order ID`),(SELECT product.`Product Name` FROM products product WHERE product.ID=movement.`Product ID`) FROM `inventory transactions` movement WHERE EXISTS (SELECT 1 FROM `inventory transaction types` kind WHERE kind.ID=movement.`Transaction Type` AND kind.`Type Name`='Sold') AND EXISTS (SELECT 1 FROM products product WHERE product.ID=movement.`Product ID`);",
   'Use Customer Order ID, not Purchase Order ID, for the optional sales linkage. These links are all NULL in the dump, so retain Sold movements and show NULL resolved order/customer instead of inventing links.', 'left_join', 'Sold|inventory|optional customer order|product', 'typed outer join|EXISTS with scalar lookups'),
 S(86, 'List Purchased inventory transactions with product name and optional purchase order ID and supplier company, retaining movements without purchase links.',
   "SELECT movement.`Transaction ID`,purchase.`Purchase Order ID`,supplier.Company,product.`Product Name` FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` LEFT JOIN `purchase orders` purchase ON purchase.`Purchase Order ID`=movement.`Purchase Order ID` LEFT JOIN suppliers supplier ON supplier.ID=purchase.`Supplier ID` JOIN products product ON product.ID=movement.`Product ID` WHERE kind.`Type Name`='Purchased';",
   "SELECT movement.`Transaction ID`,(SELECT purchase.`Purchase Order ID` FROM `purchase orders` purchase WHERE purchase.`Purchase Order ID`=movement.`Purchase Order ID`),(SELECT supplier.Company FROM `purchase orders` purchase JOIN suppliers supplier ON supplier.ID=purchase.`Supplier ID` WHERE purchase.`Purchase Order ID`=movement.`Purchase Order ID`),(SELECT product.`Product Name` FROM products product WHERE product.ID=movement.`Product ID`) FROM `inventory transactions` movement WHERE movement.`Transaction Type` IN (SELECT ID FROM `inventory transaction types` WHERE `Type Name`='Purchased') AND EXISTS (SELECT 1 FROM products product WHERE product.ID=movement.`Product ID`);",
   'Resolve the numeric Transaction Type by lookup name. All purchase-order links are NULL in this dump; preserve valid-product Purchased movements and report missing header/supplier information as NULL.', 'left_join', 'Purchased|inventory|optional purchase order|supplier', 'five-table typed outer join|correlated lookup and membership'),
 S(87, 'For each product with Sold inventory transactions return all transactions tied for its largest Sold quantity, showing product ID, transaction ID and quantity.',
   "SELECT `Product ID`,`Transaction ID`,Quantity FROM (SELECT movement.`Product ID`,movement.`Transaction ID`,movement.Quantity,DENSE_RANK() OVER (PARTITION BY movement.`Product ID` ORDER BY movement.Quantity DESC) position FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE kind.`Type Name`='Sold' AND movement.Quantity IS NOT NULL) ranked WHERE position=1;",
   "SELECT movement.`Product ID`,movement.`Transaction ID`,movement.Quantity FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE kind.`Type Name`='Sold' AND movement.Quantity=(SELECT MAX(peer.Quantity) FROM `inventory transactions` peer JOIN `inventory transaction types` peer_kind ON peer_kind.ID=peer.`Transaction Type` WHERE peer_kind.`Type Name`='Sold' AND peer.`Product ID`<=>movement.`Product ID`);",
   'Largest means a single Sold transaction quantity, not the sum sold. All equal maximum transactions survive; products with no known Sold quantity are absent.', 'topn_rank', 'Sold|largest quantity|per product|include ties', 'typed DENSE_RANK|correlated typed MAX'),
 S(88, 'For every product show On Hold inventory quantity and quantity on sales details whose Date Allocated is NULL, using zero for missing records.',
   "SELECT product.ID,COALESCE(held.quantity,0),COALESCE(unallocated.quantity,0) FROM products product LEFT JOIN (SELECT movement.`Product ID` product_id,SUM(movement.Quantity) quantity FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE kind.`Type Name`='On Hold' GROUP BY movement.`Product ID`) held ON held.product_id=product.ID LEFT JOIN (SELECT `Product ID` product_id,SUM(Quantity) quantity FROM `order details` WHERE `Date Allocated` IS NULL GROUP BY `Product ID`) unallocated ON unallocated.product_id=product.ID;",
   "SELECT product.ID,COALESCE((SELECT SUM(movement.Quantity) FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE kind.`Type Name`='On Hold' AND movement.`Product ID`=product.ID),0),COALESCE((SELECT SUM(line.Quantity) FROM `order details` line WHERE line.`Product ID`=product.ID AND line.`Date Allocated` IS NULL),0) FROM products product;",
   'On Hold ledger rows and unallocated sales lines are different concepts, so neither total is assumed to reconcile. Independent aggregates prevent fanout; no header status inference is made.', 'computed', 'On Hold|unallocated|inventory|sales quantity', 'two preaggregated outer joins|independent scalar sums'),
 S(89, 'Return products whose total Sold inventory quantity exceeds their total Purchased inventory quantity, showing product ID and both quantities.',
   "SELECT movement.`Product ID`,SUM(CASE WHEN kind.`Type Name`='Sold' THEN movement.Quantity ELSE 0 END),SUM(CASE WHEN kind.`Type Name`='Purchased' THEN movement.Quantity ELSE 0 END) FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` GROUP BY movement.`Product ID` HAVING SUM(CASE WHEN kind.`Type Name`='Sold' THEN movement.Quantity ELSE 0 END)>SUM(CASE WHEN kind.`Type Name`='Purchased' THEN movement.Quantity ELSE 0 END);",
   "WITH totals AS (SELECT product.ID,COALESCE((SELECT SUM(movement.Quantity) FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE movement.`Product ID`=product.ID AND kind.`Type Name`='Sold'),0) sold,COALESCE((SELECT SUM(movement.Quantity) FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE movement.`Product ID`=product.ID AND kind.`Type Name`='Purchased'),0) purchased FROM products product) SELECT ID,sold,purchased FROM totals WHERE sold>purchased;",
   'Compare recorded totals only, excluding Waste and On Hold. A positive difference is not proof of negative stock because the ledger does not establish opening inventory.', 'group_having', 'inventory|Sold greater than Purchased|product', 'conditional HAVING|correlated totals filter'),
 S(90, 'For each inventory type name show average and maximum calendar days between transaction creation and modification, using rows with both timestamps.',
   "SELECT kind.`Type Name`,ROUND(AVG(DATEDIFF(movement.`Transaction Modified Date`,movement.`Transaction Created Date`)),2),MAX(DATEDIFF(movement.`Transaction Modified Date`,movement.`Transaction Created Date`)) FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE movement.`Transaction Created Date` IS NOT NULL AND movement.`Transaction Modified Date` IS NOT NULL GROUP BY kind.`Type Name`;",
   "SELECT DISTINCT kind.`Type Name`,ROUND(AVG(DATEDIFF(movement.`Transaction Modified Date`,movement.`Transaction Created Date`)) OVER (PARTITION BY kind.`Type Name`),2),MAX(DATEDIFF(movement.`Transaction Modified Date`,movement.`Transaction Created Date`)) OVER (PARTITION BY kind.`Type Name`) FROM `inventory transactions` movement JOIN `inventory transaction types` kind ON kind.ID=movement.`Transaction Type` WHERE movement.`Transaction Created Date` IS NOT NULL AND movement.`Transaction Modified Date` IS NOT NULL;",
   'This measures calendar-date distance, not business days or duration spent in a status. Negative values are retained as recorded; no timestamp is substituted for a missing one.', 'date', 'inventory type|modified date|average days', 'grouped date aggregates|window date aggregates'),
 S(91, 'For each customer with sales details show customer ID, city, discounted line revenue and percentage of the revenue in that customer city.',
   "WITH sales AS (SELECT customer.ID,customer.City,SUM(line.Quantity*line.`Unit Price`*(1-line.Discount)) revenue FROM customers customer JOIN orders ord ON ord.`Customer ID`=customer.ID JOIN `order details` line ON line.`Order ID`=ord.`Order ID` GROUP BY customer.ID,customer.City) SELECT ID,City,ROUND(revenue,2),ROUND(100*revenue/NULLIF(SUM(revenue) OVER (PARTITION BY City),0),4) FROM sales;",
   "WITH sales AS (SELECT customer.ID,customer.City,SUM(line.Quantity*line.`Unit Price`*(1-line.Discount)) revenue FROM customers customer JOIN orders ord ON ord.`Customer ID`=customer.ID JOIN `order details` line ON line.`Order ID`=ord.`Order ID` GROUP BY customer.ID,customer.City) SELECT current_sale.ID,current_sale.City,ROUND(current_sale.revenue,2),ROUND(100*current_sale.revenue/NULLIF((SELECT SUM(peer.revenue) FROM sales peer WHERE peer.City<=>current_sale.City),0),4) FROM sales current_sale;",
   'City means customer City, not Ship City. Shares use unrounded discounted revenue; NULL cities, if present, form one peer group. A zero city denominator yields NULL.', 'computed', 'customer|city revenue share|percentage', 'city partition window|correlated city denominator'),
 S(92, 'For each employee find the customer or customers contributing their highest discounted revenue, returning employee ID, customer ID and revenue, retaining ties.',
   "WITH sales AS (SELECT ord.`Employee ID` employee_id,ord.`Customer ID` customer_id,SUM(line.Quantity*line.`Unit Price`*(1-line.Discount)) revenue FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` GROUP BY ord.`Employee ID`,ord.`Customer ID`), ranked AS (SELECT sales.*,DENSE_RANK() OVER (PARTITION BY employee_id ORDER BY revenue DESC) position FROM sales WHERE revenue IS NOT NULL) SELECT employee_id,customer_id,ROUND(revenue,2) FROM ranked WHERE position=1;",
   "WITH sales AS (SELECT ord.`Employee ID` employee_id,ord.`Customer ID` customer_id,SUM(line.Quantity*line.`Unit Price`*(1-line.Discount)) revenue FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` GROUP BY ord.`Employee ID`,ord.`Customer ID`) SELECT employee_id,customer_id,ROUND(revenue,2) FROM sales current_sale WHERE revenue=(SELECT MAX(peer.revenue) FROM sales peer WHERE peer.employee_id<=>current_sale.employee_id);",
   'Unknown revenue totals do not compete. Rank customers by each employee own revenue, not global customer revenue or order counts. Tie comparison uses unrounded revenue; return every maximum customer.', 'topn_rank', 'employee|best customer|revenue|include ties', 'DENSE_RANK on customer totals|correlated maximum'),
 S(93, 'For each sold product show category, product ID, discounted revenue and cumulative category revenue in descending revenue then ID order.',
   "WITH sales AS (SELECT product.Category,product.ID,SUM(line.Quantity*line.`Unit Price`*(1-line.Discount)) revenue FROM products product JOIN `order details` line ON line.`Product ID`=product.ID GROUP BY product.Category,product.ID) SELECT Category,ID,ROUND(revenue,2),ROUND(SUM(revenue) OVER (PARTITION BY Category ORDER BY revenue DESC,ID ROWS UNBOUNDED PRECEDING),2) FROM sales;",
   "WITH sales AS (SELECT product.Category,product.ID,SUM(line.Quantity*line.`Unit Price`*(1-line.Discount)) revenue FROM products product JOIN `order details` line ON line.`Product ID`=product.ID GROUP BY product.Category,product.ID) SELECT current_sale.Category,current_sale.ID,ROUND(current_sale.revenue,2),ROUND((SELECT SUM(peer.revenue) FROM sales peer WHERE peer.Category<=>current_sale.Category AND ((current_sale.revenue IS NULL AND (peer.revenue IS NOT NULL OR peer.ID<=current_sale.ID)) OR peer.revenue>current_sale.revenue OR (peer.revenue=current_sale.revenue AND peer.ID<=current_sale.ID))),2) FROM sales current_sale;",
   'Sold here means a product present in order details, not the inventory Sold type. Unknown product totals sort last and contribute no known value to the cumulative sum. Compute each product total before the running sum; ID breaks revenue ties and the current product is included.', 'topn_rank', 'product|category|cumulative revenue', 'ordered SUM window|correlated revenue prefix'),
 S(94, 'Allocate each order Shipping Fee to its lines in proportion to gross line value; return detail ID and allocated fee rounded to four decimals.',
   "SELECT ID,ROUND(`Shipping Fee`*gross/NULLIF(SUM(gross) OVER (PARTITION BY order_id),0),4) FROM (SELECT line.ID,line.`Order ID` order_id,line.Quantity*line.`Unit Price` gross,ord.`Shipping Fee` FROM `order details` line JOIN orders ord ON ord.`Order ID`=line.`Order ID`) values_by_line;",
   "SELECT line.ID,ROUND(ord.`Shipping Fee`*line.Quantity*line.`Unit Price`/NULLIF((SELECT SUM(peer.Quantity*peer.`Unit Price`) FROM `order details` peer WHERE peer.`Order ID`=line.`Order ID`),0),4) FROM `order details` line JOIN orders ord ON ord.`Order ID`=line.`Order ID`;",
   'Gross value means Quantity times Unit Price before discount. Do not round weights before allocation; final rounded shares may differ slightly from the header fee. Zero denominator or NULL fee yields NULL.', 'computed', 'shipping allocation|line value|proportional', 'window allocation denominator|correlated order denominator'),
 S(95, 'For each product return selling-price gross-margin percentage and cost-based markup percentage, both rounded to two decimals and guarded against zero denominators.',
   "SELECT ID,ROUND(100*(`List Price`-`Standard Cost`)/NULLIF(`List Price`,0),2),ROUND(100*(`List Price`-`Standard Cost`)/NULLIF(`Standard Cost`,0),2) FROM products;",
   "SELECT ID,CASE WHEN `List Price`=0 THEN NULL ELSE ROUND(100-100*`Standard Cost`/`List Price`,2) END,CASE WHEN `Standard Cost`=0 THEN NULL ELSE ROUND(100*`List Price`/`Standard Cost`-100,2) END FROM products;",
   'Margin divides profit by selling price; markup divides by cost. These are catalogue ratios, not realized order profit. Zero denominators and unknown inputs produce NULL.', 'computed', 'gross margin|markup|percent|zero denominator', 'NULLIF profit ratios|CASE complement ratios'),
 S(96, 'Return each customer active in at least two different order months, with the number of active year-months and first and last active month.',
   "SELECT `Customer ID`,COUNT(DISTINCT DATE_FORMAT(`Order Date`,'%Y-%m')),MIN(DATE_FORMAT(`Order Date`,'%Y-%m')),MAX(DATE_FORMAT(`Order Date`,'%Y-%m')) FROM orders WHERE `Order Date` IS NOT NULL GROUP BY `Customer ID` HAVING COUNT(DISTINCT DATE_FORMAT(`Order Date`,'%Y-%m'))>=2;",
   "WITH months AS (SELECT DISTINCT `Customer ID` customer_id,DATE_FORMAT(`Order Date`,'%Y-%m') month_key FROM orders WHERE `Order Date` IS NOT NULL), scored AS (SELECT customer_id,COUNT(*) OVER (PARTITION BY customer_id) quantity,MIN(month_key) OVER (PARTITION BY customer_id) first_month,MAX(month_key) OVER (PARTITION BY customer_id) last_month FROM months) SELECT DISTINCT customer_id,quantity,first_month,last_month FROM scored WHERE quantity>=2;",
   'An active month contains at least one dated order. Month keys include year; they need not be consecutive. Repeated orders in one month count once.', 'group_having', 'customer|active months|first month|last month', 'HAVING distinct month count|deduplicated month windows'),
 S(97, 'Find consecutive dated orders for a customer separated by more than 30 calendar days; show customer ID, later order ID and gap days.',
   "WITH gaps AS (SELECT `Customer ID` customer_id,`Order ID` order_id,DATEDIFF(`Order Date`,LAG(`Order Date`) OVER (PARTITION BY `Customer ID` ORDER BY `Order Date`,`Order ID`)) gap_days FROM orders WHERE `Order Date` IS NOT NULL) SELECT customer_id,order_id,gap_days FROM gaps WHERE gap_days>30;",
   "WITH gaps AS (SELECT ord.`Customer ID` customer_id,ord.`Order ID` order_id,DATEDIFF(ord.`Order Date`,(SELECT MAX(prior.`Order Date`) FROM orders prior WHERE prior.`Customer ID`<=>ord.`Customer ID` AND (prior.`Order Date`,prior.`Order ID`)<(ord.`Order Date`,ord.`Order ID`))) gap_days FROM orders ord WHERE ord.`Order Date` IS NOT NULL) SELECT customer_id,order_id,gap_days FROM gaps WHERE gap_days>30;",
   'More than is strict >30, not >=30. Calendar-day gaps ignore time-of-day; first orders have NULL gaps and are excluded. Equal-date orders are sequenced by ID.', 'topn_rank', 'customer|consecutive orders|more than 30 days', 'LAG filtered gap|correlated prior maximum'),
 S(98, 'For every employee show discounted revenue in first and second quarters of 2006 and Q2 minus Q1, using zeros for missing sales.',
   "SELECT employee.ID,ROUND(COALESCE(SUM(CASE WHEN ord.`Order Date`>='2006-01-01' AND ord.`Order Date`<'2006-04-01' THEN line.Quantity*line.`Unit Price`*(1-line.Discount) ELSE 0 END),0),2),ROUND(COALESCE(SUM(CASE WHEN ord.`Order Date`>='2006-04-01' AND ord.`Order Date`<'2006-07-01' THEN line.Quantity*line.`Unit Price`*(1-line.Discount) ELSE 0 END),0),2),ROUND(COALESCE(SUM(CASE WHEN ord.`Order Date`>='2006-04-01' AND ord.`Order Date`<'2006-07-01' THEN line.Quantity*line.`Unit Price`*(1-line.Discount) WHEN ord.`Order Date`>='2006-01-01' AND ord.`Order Date`<'2006-04-01' THEN -line.Quantity*line.`Unit Price`*(1-line.Discount) ELSE 0 END),0),2) FROM employees employee LEFT JOIN orders ord ON ord.`Employee ID`=employee.ID LEFT JOIN `order details` line ON line.`Order ID`=ord.`Order ID` GROUP BY employee.ID;",
   "WITH quarterly AS (SELECT employee.ID,COALESCE((SELECT SUM(line.Quantity*line.`Unit Price`*(1-line.Discount)) FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` WHERE ord.`Employee ID`=employee.ID AND ord.`Order Date`>='2006-01-01' AND ord.`Order Date`<'2006-04-01'),0) first_quarter,COALESCE((SELECT SUM(line.Quantity*line.`Unit Price`*(1-line.Discount)) FROM orders ord JOIN `order details` line ON line.`Order ID`=ord.`Order ID` WHERE ord.`Employee ID`=employee.ID AND ord.`Order Date`>='2006-04-01' AND ord.`Order Date`<'2006-07-01'),0) second_quarter FROM employees employee) SELECT ID,ROUND(first_quarter,2),ROUND(second_quarter,2),ROUND(second_quarter-first_quarter,2) FROM quarterly;",
   'Quarter assignment uses Order Date; first compute unrounded revenue then round displayed totals and difference. This is a difference in currency, not percentage growth.', 'cond_agg', 'employee|quarter revenue|Q2 minus Q1', 'conditional outer aggregate|correlated quarterly totals'),
 S(99, 'For every order show detail count, invoice count and gross line total without multiplying counts or money by joining the two child tables together.',
   "SELECT ord.`Order ID`,COALESCE(details.quantity,0),COALESCE(invoiced.quantity,0),ROUND(COALESCE(details.gross,0),2) FROM orders ord LEFT JOIN (SELECT `Order ID` order_id,COUNT(*) quantity,SUM(Quantity*`Unit Price`) gross FROM `order details` GROUP BY `Order ID`) details ON details.order_id=ord.`Order ID` LEFT JOIN (SELECT `Order ID` order_id,COUNT(*) quantity FROM invoices GROUP BY `Order ID`) invoiced ON invoiced.order_id=ord.`Order ID`;",
   "SELECT ord.`Order ID`,(SELECT COUNT(*) FROM `order details` line WHERE line.`Order ID`=ord.`Order ID`),(SELECT COUNT(*) FROM invoices invoice WHERE invoice.`Order ID`=ord.`Order ID`),ROUND(COALESCE((SELECT SUM(line.Quantity*line.`Unit Price`) FROM `order details` line WHERE line.`Order ID`=ord.`Order ID`),0),2) FROM orders ord;",
   'Details and invoices are independently one-to-many from orders. Preaggregation or scalar aggregates avoid fanout; SUM(DISTINCT amount) would wrongly merge equal-valued real lines.', 'left_join', 'order|invoice count|detail count|fanout', 'separate child preaggregations|independent scalar aggregates'),
 S(100, 'For every category show its average List Price, the unweighted average of category averages and their signed difference, rounded to four decimals.',
   "WITH averages AS (SELECT Category,AVG(`List Price`) mean_price FROM products GROUP BY Category) SELECT Category,ROUND(mean_price,4),ROUND(AVG(mean_price) OVER (),4),ROUND(mean_price-AVG(mean_price) OVER (),4) FROM averages;",
   "WITH averages AS (SELECT Category,AVG(`List Price`) mean_price FROM products GROUP BY Category) SELECT Category,ROUND(mean_price,4),ROUND((SELECT AVG(peer.mean_price) FROM averages peer),4),ROUND(mean_price-(SELECT AVG(peer.mean_price) FROM averages peer),4) FROM averages;",
   'Each category average has equal weight regardless of product count, so this is not the overall product AVG(List Price). NULL prices and NULL category averages are ignored by AVG; subtraction precedes rounding.', 'computed', 'category averages|unweighted average|price deviation', 'window average of averages|scalar average of averages'),
]
